	\label{lem:3.65}
	Let $u \in L^{2}(0, T;V_{g})$,  then the function $R_{g}u$ defined by
	\begin{equation}
		\label{eq:2.9}
		\begin{aligned}
		(R_{g}u(t), v)_{g} = \left(P_{g}\left(\dfrac{\nabla g}{g} \cdot \nabla \right)u, v\right)_{g} = \left(\left(\dfrac{\nabla g}{g} \cdot \nabla \right)u, v\right)_{g}, \forall \, v\in V_{g}, 
		\end{aligned}
	\end{equation}
	belongs to $L^{2}(0,T; H_{g})$, and therefore also belongs to $L^{2}(0, T; V^{*}_{g})$. Moreover,
	\begin{equation}
		\label{eq:2.10}
		\begin{aligned}
			\|R_{g}u(t)\|_{g} \le  \dfrac{\|\nabla g\|_{\infty}}{m_{0}}\|u\|_{V_{g}},\,\, for\,\, a.e. \,\,t \in (0, T),
		\end{aligned}
	\end{equation}
	and
	\begin{equation}
		\label{eq:2.11}
		\begin{aligned}
			\|R_{g}u(t)\|_{V^{*}} \le  \dfrac{\|\nabla g\|_{\infty}}{m_{0}\lambda^{1/2}_{1}}\|u\|_{V_{g}},\,\, for\,\, a.e. \,\,t \in (0, T).
		\end{aligned}
	\end{equation}

To prove \eqref{eq:2.10}, by \eqref{eq:2.9} and duality, for any $v \in H_{g}$, 
	\begin{equation}
		\label{eq:3.67}
		\begin{aligned}
		|(R_{g}u,v)_{g}| &= \left|\int_{\mathcal{O}}^{}\sum_{i,j=1}^{2}(\frac{\partial_{i}g }{g}\partial_{i}u_{j}) v_{j}gdx \right|\le \int_{\mathcal{O}}^{}|\frac{\nabla g}{g}||\nabla u| |v| g dx
		\\& \le \frac{\|\nabla g\|_{\infty}}{m_{0}} \int_{\mathcal{O}}^{}|\nabla u| |v| g dx
	 \le \frac{\|\nabla g\|_{\infty}}{m_{0}} \|u\|_{V_{g}} \|v\|_{g}.
		\end{aligned}
	\end{equation}
	By the definition of the norm, $\| R_{g}u(t)\|_{g} = \underset{|v| \le 1}{\sup} |(R_{g}u,v)_{g}| \le \frac{\|\nabla g\|_{\infty}}{m_{0}} \|u\|_{V_{g}}$. Since $u \in L^{2}(0,T; V_{g})$, this estimate implies that $R_{g}u \in L^{2}(0,T; H_{g})$. Similarly, 
	\begin{equation}
		\label{eq:3.68}
		\begin{aligned}
			\| R_{g}u(t)\|_{V^{*}} = \underset{v\in V_{g}, |v| \le 1}{sup} |(R_{g}u,v)_{g}|
			\le \frac{\|\nabla g\|_{\infty}}{m_{0}} \|u\|_{V_{g}} \|v\|_{g}
			\le \frac{\|\nabla g\|_{\infty}}{m_{0} \lambda^{1/2}_{1}} \|u\|_{V_{g}} \|v\|_{V_{g}}. 
		\end{aligned}
	\end{equation}
	The last step of the inequality employs the Poincar\'e inequality.

For any $(x, y)$, by the fundamental theorem of calculus, the function can be written as
	\begin{equation}
		\label{eq:1.4}
		\mathbf{f}(x,y) = \int_{-\infty}^{x} \partial_{1}\mathbf{f}(s,y)gds = - \int_{x}^{-\infty} \partial_{1}\mathbf{f}(s,y)gds.
	\end{equation}
	\begin{equation}
		\label{eq:1.5}
		\mathbf{g}(x,y) = \int_{-\infty}^{y} \partial_{2}\mathbf{g}(x,t)gdt = - \int_{y}^{-\infty} \partial_{2}\mathbf{g}(x,t)gdt.
	\end{equation}
	By \eqref{eq:1.4} we have
	\begin{equation}
		\label{eq:1.6}
		|\mathbf{f}(x,y)| = \frac{1}{2} \left|\left[ \int_{-\infty}^{x}\partial_{1}\mathbf{f}(s,y)gds +\int_{x}^{-\infty} -\partial_{1}\mathbf{f}(s,y)gds\right]\right| \le \frac{1}{2} \int_{-\infty}^{\infty} |\partial_{1}\mathbf{f}(s,y)g|ds. 
	\end{equation}
	In the same way 
	\begin{equation}
		\label{eq:1.7}
		|\mathbf{g}(x,y)| \le \frac{1}{2} \int_{-\infty}^{\infty} |\partial_{2}\mathbf{g}(x,t)g|dt.
	\end{equation}
	Using \eqref{eq:1.6} and \eqref{eq:1.7}, and integrating with respect to $x$ and $y$,
	\begin{equation}
		\label{eq:1.8}
		\left|\int_{-\infty}^{\infty}\mathbf{f}(x,y)\mathbf{g}(x,y)dxdy \right|\le \frac{1}{4} \int_{-\infty}^{\infty} |\partial_{1}\mathbf{f}(s,y)g|ds\int_{-\infty}^{\infty} |\partial_{2}\mathbf{g}(x,t)g|dt.
	\end{equation}
	\eqref{eq:1.8} is equivalent to
	\begin{equation}
		\label{eq:1.9}
		\| \mathbf{f}\mathbf{g}\|_{L^{1}} \le \frac{1}{4} \|\partial_{1}\mathbf{f}\|_{L^{1}}\|\partial_{2}\mathbf{g}\|_{L^{1}}.
	\end{equation} 
	Replacing $\mathbf{f}$ and $\mathbf{g}$ by $\mathbf{f}^{2}$  and $\mathbf{g}^{2}$ , respectively, it yields 
	\begin{equation}
		\label{eq:1.10}
		\| \mathbf{f}^{2}\mathbf{g}^{2}\|_{L^{1}} \le  \|\mathbf{f}\partial_{1}\mathbf{f}\|_{L^{1}}\|\mathbf{g}\partial_{2}\mathbf{g}\|_{L^{1}}.
	\end{equation}
	Using the Cauchy-Schwarz inequality twice gives
	\begin{equation}
		\label{eq:1.11}
		\begin{aligned}
		\| \mathbf{f}^{2}\mathbf{g}^{2}\|_{L^{1}} &\le  \|\mathbf{f}\|_{L^{2}}\|\mathbf{g}\|_{L^{2}}\|\partial_{1}\mathbf{f}\|_{L^{2}}\|\partial_{2}\mathbf{g}\|_{L^{2}}
		\\&\le \|\mathbf{f}\|_{L^{2}}\|\mathbf{g}\|_{L^{2}}\|\nabla\mathbf{f}\|_{L^{2}}\|\nabla\mathbf{g}\|_{L^{2}}.
	\end{aligned}
	\end{equation}
	Therefore, the proof of the first inequality is completed. Setting $\mathbf{f} =\mathbf{g}$ in \eqref{eq:1.11}, and using the Cauchy-Schwarz inequality, it yields
\begin{equation}
	\label{eq:1.12}
	\|\mathbf{f}\|^{4}_{L^{4}} \le 2 \|\mathbf{f}\|^{2}_{L^{2}}\| \nabla\mathbf{f}\|^{2}_{L^{2}}.
\end{equation}

\label{rem:1.3}
	From Lemma \ref{lem:1.2}, it follows that for any $u \in H_{g}$,
	\begin{equation}
		\label{eq:1.16}
	\|u \|^{4}_{L^{4}} \, \le \,  \frac{2M_{0}}{m^{2}_{0}}\, \|u\|^{2}_{{g}} \,\|u \|^{2}_{V_{g}}.
	\end{equation}
If $u = (u_{1}, u_{2})$, then $\| u\|^{2}_{g} $ $= \sum_{i=1}^{2}(u_{i},u_{i})_{g}$ and $\| u\|^{2}_{V_{g}}$ $= \sum_{i,j=1}^{2} \int_{\mathcal{O}}^{}\frac{\partial{u_{j}}}{\partial{x_{i}}}\frac{\partial{v_{j}}}{\partial{x_{i}}}gdx$. The bound given by \eqref{eq:1.16} holds for both bounded and  unbounded domains.

\label{prop:1.4}
	For a given $r > 0$, let $B_{r}$ denote the $L^{4}(\mathcal{O})$ ball in $V_{g} : B_{r} = \{v \in V_{g} :\|v\|_{L^{4}(\mathcal{O})} \le r \}$. Define the nonlinear operator $F$ on $V_{g}$ by $F(u) :=-\nu A_{g}u - B_{g}(u,u)-\nu R_{g}u$. Then for  any $0 < \varepsilon \le \frac{9 \nu }{16L}$, where $L$ is the constant that appears in the condition (\textbf{A3}), the pair $(F, \sqrt{\varepsilon}\sigma)$  is monotone in $B_{r}$ : i.e. for any $u \in  V_{g}$ and $v \in B_{r}$, then
	\begin{equation}
		\label{eq:1.13}
		(F(u)-F(v),u-v)_{g} - \frac{r^{4}}{\nu^{3}}\|u-v\|^{2}_{g} + \varepsilon\|\sigma(t,u) -\sigma(t,v)\|^{2}_{L_{Q}} \le 0. 
	\end{equation}

We first note that
	\begin{equation}
		\label{eq:1.14}
		\begin{aligned}
		(F(u)-F(v),u-v)_{g} &=-\nu(A_{g}(u-v),u-v)_{g} - (B_{g}(u,u)-B_{g}(v,v), u-v)_{g} 
		\\& - \nu(R_{g}(u-v), u-v)_{g}.
		\end{aligned}
	\end{equation}
	By the definition of operator $A_{g}$, we have $(A_{g}u,u)_{g} = \|u\|^{2}_{V_{g}}$. Using \eqref{eq:2.3} and the bilinearity of the operator $B_{g}$, it follows that $(B_{g}(u,u), u-v )_{g} = -(B(u,u-v),v)_{g}$ and $(B_{g}(v,v), u-v )_{g} = -(B(v,u-v),v)_{g}$. Hence,
	\begin{equation}
		\label{eq:1.15}
		(B_{g}(u,u)-B_{g}(v,v), u-v )_{g} = -(B_{g}(u-v,u-v),v)_{g}.
	\end{equation}
	By \eqref{eq:1.16} and H\"older inequality, we obtain
	\begin{equation}
		\label{eq:1.17}
		\begin{aligned}
			|(B_{g}(u,u)-B_{g}(v,v), u-v )_{g}| &\le \|u-v\|_{L^{4}(\mathcal{O})}\|u-v\|_{g}\|v\|_{L^{4}(\mathcal{O})}
			\\& \le  \|u-v\|^{1/2}_{g} \|u-v\|^{3/2}_{V_{g}} \|v\|_{L^{4}(\mathcal{O})}
			\\& \le \dfrac{\nu}{2} \| u-v\|^{2}_{V_{g}} + \dfrac{27}{32\nu^{3}}\| u-v\|^{2}_{g} \|v\|^{4}_{L^{4}(\mathcal{O})}.
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of equation \eqref{eq:1.14}, by \eqref{eq:1.2} and Poincar\'e inequality, we obtain
	\begin{equation}
		\label{eq:1.18}
		\begin{aligned}
			|(R_{g}u-R_{g}v, u-v)_{g}| &= |(P_{g} (\frac{1}{g}(\nabla g \cdot \nabla)(u-v), u-v )_{g}| 
			\\& \le \dfrac{\| \nabla g\|_{\infty}}{m_{0}\lambda^{1/2}_{1}}\|u-v\|^{2}_{V_{g}}  
			 \le \dfrac{1}{16}\|u-v\|^{2}_{V_{g}}.
		\end{aligned}
	\end{equation}
	By \eqref{eq:1.17}, \eqref{eq:1.18}, and the definition of the operator $F$,  we get
	\begin{equation}
		\label{eq:1.19}
		(F(u)-F(v),u-v)_{g} \le -\frac{9 \nu}{16} \|u-v\|^{2}_{V_{g}} + \dfrac{27r^{4}}{32\nu^{3}}\| u-v\|^{2}_{g},
	\end{equation}
	since $\| v \|_{L^{4}(\mathcal{O})} \le r$ . Combining this estimate with condition (\textbf{A3}) and $\varepsilon \le \frac{9 \nu}{16L}$ completes the proof.

\label{prop:1.22} 
	Suppose (\textbf{A1})--(\textbf{A3}) hold, let $u^{\varepsilon}_{n}$ denote the unique strong solution of finite-dimensional system \eqref{eq:1.20} in $C([0, T]; H_{n})$. Then, for every $T > 0$, $N > 0$, $ 0 < \varepsilon \le \varepsilon_{0}$ and $\mathbf{E} \|u(0)\|^{2}_{g} < \infty$, the following estimates hold:
	\\
	\\
	1. If $f \in L^{2}(0,T; V^{*})$ and  $\varepsilon_{0} = \min\{\frac{3\nu}{4K}, \frac{7\nu}{8K(1+2c^{2}_{2})} \}$, then, for all $t \in [0,T]$,
	\begin{equation}
		\label{eq:4.38}
		\begin{aligned}
		\mathbf{E}(\| u^{\varepsilon}_{n}(t) \|^{2}_{g}) + \nu\int_{0}^{t}\mathbf{E}\| u^{\varepsilon}_{n}(s) \|^{2}_{V_{g}}ds \le C_{1}\left( \mathbf{E}\| u(0)\|^{2}_{g} + \mathbf{E}\int_{0}^{t}\| f(s)\|^{2}_{V^{*}}ds + 1 \right),
		\end{aligned}
	\end{equation}
	and 
	\begin{equation}
		\label{eq:4.39}
		\begin{aligned}
		\mathbf{E}\left[\underset{0 \le t \le T}{\sup}\left(\|u^{\varepsilon}_{n}(t)\|^{2}_{g} + \nu\int_{0}^{t} \| u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds \right)\right] \le C_{1} \left(\mathbf{E}\|u(0\|^{2}_{g} + \mathbf{E}\int_{0}^{T}\| f(s)\|^{2}_{V^{*}}ds +1 \right),
		\end{aligned}
	\end{equation}
	where $C_{1} = C_{1}(\varepsilon_{0}, \nu , T)$ is a constant independent of $\varepsilon$, $u_{0}$ and $N$. 
	\\
	\\
	2. If $f \in L^{2}(0,T; V^{*})$, let $\delta > 0$ and $\varepsilon_{0} = \frac{7\nu}{8K}$, then for all $t \in [0,T]$,
	\begin{equation}
		\label{eq:1.70}
		\begin{aligned}
			\mathbf{E}e^{-\delta t}\| u^{\varepsilon}_{n}(t)\|^{2}_{g}  + \nu\mathbf{E}\int_{0}^{t}e^{-\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} ds \le C_{2}\left( \mathbf{E}\|u(0) \|^{2}_{g} + \mathbf{E}\int_{0}^{t}e^{-\delta s} \| f(s)\|^{2}_{V^{*}}ds + 1 \right),
		\end{aligned}
	\end{equation}
	where $C_{2} = C_{2}(\varepsilon_{0}, \nu , T) $ is a constant independent of $\varepsilon$, $u_{0}$ and $N$. 
	\\
	\\
	3. If $f \in L^{4}([0,T]; V^{*})$, $\mathbf{E}\|u(0)\|^{4}_{g} < \infty$, let $\delta > 0$ and $\varepsilon_{0} = \min\{\frac{\nu}{8K}, \frac{11\nu}{8K(3+c^{2}_{2})}\}$, then for all $t \in [0,T]$,
	\begin{equation}
		\label{eq:1.75}
		\begin{aligned}
			\mathbf{E}e^{-2\delta t}\| u^{\varepsilon}_{n}(t)\|^{4}_{g}  + 3\nu \mathbf{E} \int_{0}^{t}e^{-2\delta s} \| u^{\varepsilon}_{n}(s) \|^{2}_{V_{g}}\| u^{\varepsilon}_{n}(s) \|^{2}_{g} 	ds 
			\le C_{3}\left( \mathbf{E}\| u(0) \|^{4}_{g} + \mathbf{E} \int_{0}^{t} e^{-2\delta s}\| f(s) \|^{4}_{V^{*}}  ds + 1 \right),
		\end{aligned}
	\end{equation}
	and
	\begin{equation}	
		\label{eq:1.79}
		\begin{aligned}
			&\textbf{E}\left[ \underset{0 \le t \le T}{\sup}\left(  e^{-2\delta t} \|u^{\varepsilon}_{n}(s)\|^{4}_{g}  +  \nu \textbf{E}\int_{0}^{t}e^{-2\delta t}\| u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}}\|u^{\varepsilon}_{n}(t)\|^{2}_{g} dt \right) \right] 
			\\& \le C_{4}\left( \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} +  \textbf{E}\int_{0}^{T} e^{-2\delta t}\|f(s)\|^{4}_{V^{*}} ds + 1 \right), 
		\end{aligned}
	\end{equation}
	where $C_{3}$ and $C_{4}$ are positive constants independent of $\varepsilon$, $u_{0}$ and $N$.

Proof of \eqref{eq:4.38} and \eqref{eq:4.39}. By \eqref{eq:2.6} and It\^o formula, we can get 
	\begin{equation}
		\label{eq:4.50}
		\begin{aligned}
			d\| u^{\varepsilon}_{n}(t) \|^{2}_{g} &+ 2(\nu A_{g}u^{\varepsilon}_{n}(s) + B_{g}(u^{\varepsilon}_{n}(s), u^{\varepsilon}_{n}(s)) + \nu R_{g}u^{\varepsilon}_{n}(s) , u^{\varepsilon}_{n}(s) )_{g}dt = 2(f(s), u^{\varepsilon}_{n}(t))_{g}dt 
			\\& + \varepsilon tr(\sigma(u^{\varepsilon}_{n}(t))Q\sigma^{*}(u^{\varepsilon}_{n}(t)))dt + 2\sqrt{\varepsilon}(\sigma(u^{\varepsilon}_{n}(t))dW_{n}(t), u^{\varepsilon}_{n}(t) )_{g}.
		\end{aligned}
	\end{equation}
	By the definitions of the $A_{g}$ and $B_{g}$, we have
	\begin{equation}
		\label{eq:4.51}
		\begin{aligned}
			& d\| u^{\varepsilon}_{n}(t) \|^{2}_{g} + 2\nu\|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}} dt +  2(\nu R_{g}u^{\varepsilon}_{n}(t) , u^{\varepsilon}_{n}(t) )_{g}dt \\& = 2(f(s), u^{\varepsilon}_{n}(t))_{g}dt 
		+ \varepsilon tr(\sigma(u^{\varepsilon}_{n}(t))Q\sigma^{*}(u^{\varepsilon}_{n}(t)))dt + 2\sqrt{\varepsilon}(\sigma(u^{\varepsilon}_{n}(t))dW_{n}(t), u^{\varepsilon}_{n}(t) )_{g}.
		\end{aligned}
	\end{equation}
	For the last term on the left-hand side of \eqref{eq:4.51}, by Lemma \ref{lem:3.65} and \eqref{eq:1.2}, we have  
	\begin{equation}
		\label{eq:4.52}
		\begin{aligned}
		2\nu|( R_{g}u^{\varepsilon}_{n}(s) , u^{\varepsilon}_{n}(s) )_{g}dt	| \le 2\nu  \frac{\|\nabla g\|_{\infty}}{m_{0}\lambda^{1/2}_{1}} \|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}}dt \le \frac{\nu }{8} \|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}}dt. 
		\end{aligned}
	\end{equation}
		For the first term on the right-hand side of \eqref{eq:4.51}, by Young's inequality, we have
	\begin{equation}
		\label{eq:4.53}
		\begin{aligned}
	2|(f(s), u^{\varepsilon}_{n}(t))_{g}dt| \le  \frac{8}{\nu}\|f(t)\|^{2}_{V^{*}}dt + \frac{ \nu}{8} \|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}}dt. 
		\end{aligned}
	\end{equation}
		Define a sequence of stopping times as follows
	\[
	\tau_{N} = \inf \left\{t: \|u^{\varepsilon}_{n}(t)\|^{2}_{g} + \int_{0}^{t}\| u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} \ge N \right\}. 
	\]
	Combining \eqref{eq:4.52} - \eqref{eq:4.53} with  condition (\textbf{A2}), we get that for any $t \in [0,T]$,
	\begin{equation}
		\label{eq:4.54}
		\begin{aligned}
			\| u^{\varepsilon}_{n}(t \wedge \tau_{N}) \|^{2}_{g} + \nu \int_{0}^{t \wedge \tau_{N}}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} ds 
			& \le \|u^{\varepsilon}_{n}(0)\|^{2}_{g} + \frac{8}{\nu}  \int_{0}^{t \wedge \tau_{N}} \|f(s)\|^{2}_{V^{*}}ds 
			 \\& + \varepsilon K \int_{0}^{t \wedge \tau_{N}} \left(1+ \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} \right)ds.
		\end{aligned}
	\end{equation}
	Taking the expectation for \eqref{eq:4.54}, and $\varepsilon < \frac{3\nu}{4K} $, we have
	\begin{equation}
		\label{eq:4.56}
		\begin{aligned}
			\mathbf{E}\| u^{\varepsilon}_{n}(t \wedge \tau_{N}) \|^{2}_{g} + \nu\int_{0}^{t \wedge \tau_{N}}\mathbf{E}\| u^{\varepsilon}_{n}(s) \|^{2}_{V_{g}}ds 
			\le C_{1}\left(\mathbf{E}\| u(0)\|^{2}_{g} + \mathbf{E}\int_{0}^{t \wedge \tau_{N}}\| f(s)\|^{2}_{V^{*}}ds + 1 \right), 
		\end{aligned}
	\end{equation}
	where $C_{1} > 0$  is independent of $\varepsilon$, $u_{0}$ and $\|f(t)\|_{V^{*}}$. 
	\par 
	Taking the supremum and expectation in \eqref{eq:4.51} and using \eqref{eq:4.54}, we have that for $t\in [0, T\wedge \tau_{N}]$, 
	\begin{equation}
		\label{eq:1.63}
		\begin{aligned}
			&\textbf{E}\underset{0 \le t \le T \wedge \tau_{N}}{\sup} \left(\|u^{\varepsilon}_{n}(t) \|^{2}_{g}  + \nu \int_{0}^{t} \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds \right) 
			\\& \le \textbf{E}\|u(0)\|^{2}_{g} + \varepsilon K \textbf{E}\int_{0}^{t \wedge \tau_{N}} \left(1+ \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} \right)ds 
			\\& + \frac{8}{\nu}\textbf{E}\int_{0}^{T \wedge \tau_{N}} \| f(s)\|^{2}_{V^{*}}ds + 2\sqrt{\varepsilon} \,\textbf{E} \underset{0\le t \le T \wedge \tau_{N}}{\sup} \left|\int_{ 0}^{t } (\sigma_{n}(s, u^{\varepsilon}_{n}(s) )dW_{n}(s), u^{\varepsilon}_{n}(s))_{g} \right|.
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of \eqref{eq:1.63}, by using condition (\textbf{A2}) and Burkholder-Davis-Gundy inequality, we have 
	\begin{equation}
		\label{eq:1.64}
		\begin{aligned}
			&2\sqrt{\varepsilon} \,\textbf{E}\left[ \underset{0\le t \le T \wedge \tau_{N}}{\sup} \left|\int_{ 0}^{t } (\sigma_{n}(s, u^{\varepsilon}_{n}(s) )dW_{n}(s), u^{\varepsilon}_{n}(s))_{g} \right|  \right]
			\\& \le 2\sqrt{\varepsilon} c_{2} \textbf{E} \left[  \left(\int_{0}^{T \wedge \tau_{N}} \|\sigma_{n}(s, u^{\varepsilon}_{n}(s)\|^{2}_{L_{Q}}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds \right)^{1/2} \right]
			\\& \le  \frac{1}{2}   \textbf{E}\left[ \underset{0 \le t \le T \wedge \tau_{N} }{\sup} \|u^{\varepsilon}_{n}(t) \|^{2}_{g} \right]  + 2 \varepsilon c^{2}_{2}  \textbf{E} \left[ \int_{0}^{T \wedge \tau_{N}} \|\sigma_{n}(s, u^{\varepsilon}_{n}(s)\|^{2}_{L_{Q}} ds \right]
			\\& \le \frac{1}{2}   \textbf{E}\left[ \underset{0 \le t \le T \wedge \tau_{N} }{\sup} \|u^{\varepsilon}_{n}(t) \|^{2}_{g} \right]  + 2 \varepsilon c^{2}_{2} K \textbf{E} \left[  \int_{0}^{T \wedge \tau_{N}} \| u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} ds \right] +2 \varepsilon c^{2}_{2} KT.
		\end{aligned}
	\end{equation}
	Substituting \eqref{eq:1.64} into \eqref{eq:1.63}, we obtain that for any $t \in [0,T \wedge \tau_{N}]$,
	\begin{equation}
		\label{eq:1.65}
		\begin{aligned}
			&\textbf{E}\left[ \underset{0\le t \le T \wedge \tau_{N}}{\sup} \left( \frac{1}{2} \|u^{\varepsilon}_{n}(t) \|^{2}_{g}  + (\frac{15\nu }{8} -  \varepsilon K - 2 \varepsilon c^{2}_{2} K) \int_{0}^{t} \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds \right) \right] 
			\\&\le \textbf{E}\|u(0)\|^{2}_{g} + \frac{8}{\nu} \textbf{E} \int_{0}^{T \wedge \tau_{N}} \| f(s)\|^{2}_{V^{*}} ds 
			+ \varepsilon KT +2 \varepsilon c^{2}_{2} KT.
		\end{aligned}
	\end{equation}
	By \eqref{eq:4.56}, we have 
	\begin{equation}
		\label{eq:1.66}
		\begin{aligned}
			\nu\int_{0}^{T \wedge \tau_{N}}\mathbf{E}\| u^{\varepsilon}_{n}(s) \|^{2}_{V_{g}}ds \le C_{1}\left( \mathbf{E}\| u(0)\|^{2}_{g} + \mathbf{E}\int_{0}^{T \wedge \tau_{N}}\| f(s)\|^{2}_{V^{*}}ds + 1 \right).
		\end{aligned}
	\end{equation}
	Combining \eqref{eq:1.65}-\eqref{eq:1.66}, we obtain
	\begin{equation}
		\label{eq:1.67}
		\begin{aligned}
			\textbf{E}\underset{0\le t \le T \wedge \tau_{N}}{\sup}\|u^{\varepsilon}_{n}(t) \|^{2}_{g}\le C_{1}\left(\mathbf{E}\| u(0)\|^{2}_{g} + \textbf{E} \int_{0}^{T}\|f(s)\|^{2}_{V^{*}}ds+ 1 \right), 
		\end{aligned}
	\end{equation}
	where $ \varepsilon < \frac{7\nu }{8K(1+2c^{2}_{2})}$. It can be inferred from \eqref{eq:1.63}-\eqref{eq:1.66} that
	\begin{equation}
		\label{eq:1.68}
		\begin{aligned}
			\mathbf{E}\left[\underset{0 \le t \le T}{\sup}\left(\|u^{\varepsilon}_{n}(t)\|^{2}_{g} + \nu\int_{0}^{t} \| u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds \right)\right]  \le C_{1}\left(\mathbf{E}\| u(0)\|^{2}_{g} + \int_{0}^{T}\textbf{E}\|f(s)\|^{2}_{V^{*}}ds +1 \right), 
		\end{aligned}
	\end{equation}
	where $C_{1} >0 $ is independent of $\varepsilon$, $u_{0}$ and $N$. Since $\tau_N\to T$ almost surely as $N\to\infty$, Fatou's lemma applied to \eqref{eq:1.68} yields \eqref{eq:4.39}. This completes the proof.
	\par 
	Proof of \eqref{eq:1.70}. Let $\delta > 0$ and the function $h(t, u^{\varepsilon}_{n}) = e^{- \delta t}\| u^{\varepsilon}_{n}\|^{2}_{g}$. By \eqref{eq:1.20} and  It\^o formula, we obtain 
	\begin{equation}
		\label{eq:1.71}
		\begin{aligned}
			& de^{- \delta t}\|u^{\varepsilon}_{n}(t)\|^{2}_{g} + \delta e^{- \delta t} \|u^{\varepsilon}_{n}(t)\|^{2}_{g}dt + 2\nu e^{- \delta t}\|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}}dt + 2\nu (R_{g}u^{\varepsilon}_{n}(t), e^{- \delta t}u^{\varepsilon}_{n}(t))_{g}dt
			\\& = (f(t), 2e^{- \delta t}u^{\varepsilon}_{n}(t))_{g}dt   
			+ e^{- \delta t}\varepsilon tr(\sigma_{n}(t, u^{\varepsilon}_{n}(t)) Q\sigma^{*}_{n}(t, u^{\varepsilon}_{n}(t)))dt 
			\\& + 2\sqrt{\varepsilon}(\sigma_{n}(t, u^{\varepsilon}_{n}(t))dW_{n}(t), e^{- \delta t}u^{\varepsilon}_{n}(t))_{g}.
		\end{aligned}
	\end{equation}
	For the last term on the left-hand side of \eqref{eq:1.71}, by Lemma \ref{lem:3.65} and \eqref{eq:1.2}, we have  
	\begin{equation}
		\label{eq:4.55}
		\begin{aligned}
			2\nu|( R_{g}u^{\varepsilon}_{n}(s) , u^{\varepsilon}_{n}(s) )_{g}	| \le 2\nu e^{- \delta t}  \frac{\|\nabla g\|_{\infty}}{m_{0}\lambda^{1/2}_{1}} \|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}} \le \frac{\nu }{8}e^{- \delta t} \|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}}. 
		\end{aligned}
	\end{equation}
		For the first term on the right-hand side of \eqref{eq:4.51}, by Young's inequality, we get
	\begin{equation}
		\label{eq:4.57}
		\begin{aligned}
			2e^{- \delta t}|(f(s), u^{\varepsilon}_{n}(t))_{g}| \le  \frac{1}{\delta}e^{- \delta t}\|f(s)\|^{2}_{V^{*}} + \delta e^{- \delta t} \|u^{\varepsilon}_{n}(s)\|^{2}_{g} .   
		\end{aligned}
	\end{equation}
	Define the sequence of stopping times as follows
	\[
	\tau_{N} = \inf\{t : \max(\|u^{\varepsilon}_{n}(t)\|^{2}_{g}, \, \int_{0}^{t}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds) \ge  N\}.
	\]
	By \eqref{eq:4.55}- \eqref{eq:4.57}, taking the expectation, we obtain that for any $s \in [0,t \wedge \tau_{N}]$,
	\begin{equation}
		\label{eq:1.72}
		\begin{aligned}
			&\textbf{E} e^{- \delta (t\wedge \tau_{N})} \|u^{\varepsilon}_{n}(t \wedge \tau_{N})\|^{2}_{g} + 2\nu \textbf{E}\int_{0}^{t\wedge \tau_{N}} e^{-\delta s} \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds 
			\\& \le \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{2}_{g} 
			 + \dfrac{\nu}{8}  \textbf{E}\int_{0}^{t\wedge \tau_{N}} e^{-\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds + \dfrac{1}{\delta}\textbf{E}\int_{0}^{t\wedge \tau_{N}} e^{-\delta s}\|f(s)\|^{2}_{V^{*}}ds  
			 \\&+ \varepsilon \textbf{E}\int_{0}^{t \wedge \tau_{N}} e^{-\delta s} \|\sigma_{n}(s,u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}}ds . 
		\end{aligned}
	\end{equation}
	Combining this estimate with (\textbf{A2}) and assuming $\varepsilon < \frac{3\nu}{4K}$, we have
	\begin{equation}
		\label{eq:1.73}
		\begin{aligned}
			\textbf{E} e^{- \delta (t\wedge \tau_{N})} \|u^{\varepsilon}_{n}(t \wedge \tau_{N})\|^{2}_{g} + \nu  \textbf{E}\int_{0}^{t\wedge \tau_{N}} e^{-\delta s} \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}ds  
			  \le C_{2}\left( \mathbf{E}\|u(0) \|^{2}_{g} + \mathbf{E}\int_{0}^{t}e^{-\delta s} \| f(s)\|^{2}_{V^{*}}ds + 1 \right),
		\end{aligned}
	\end{equation}
	where $C_{2} >0 $ is independent of $\varepsilon$, $u_{0}$ and $N$. Note that we can obtain $\tau_{N} \to \infty$, a.s., as $N\to \infty$. Thus, the proof of \eqref{eq:1.70} is completed.
	\par 
	Proof of \eqref{eq:1.75} and \eqref{eq:1.79}. By the function $h(t, u^{\varepsilon}_{n}) = e^{- 2\delta t}\| u^{\varepsilon}_{n}\|^{4}_{g}$ and It\^o formula, taking the expectation, we obtain that for all $t \in [0,T]$,
		\begin{equation}
			\label{eq:1.76}
			\begin{aligned}
				&\textbf{E}e^{-2\delta t}\|u^{\varepsilon}_{n}(t)\|^{4}_{g} + 4\nu \textbf{E} \int_{0}^{t}e^{- 2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} \|u^{\varepsilon}_{n}(s)\|^{2}_{g} ds + 2\delta \textbf{E}\int_{0}^{t}e^{-2\delta s} \|u^{\varepsilon}_{n}(s)\|^{4}_{g}ds 
				\\& \le \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} -
				4\nu \textbf{E}\int_{0}^{t}e^{- 2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}(u^{\varepsilon}_{n}(s), R_{g}u^{\varepsilon}_{n}(s))_{g} ds + 
				4\textbf{E}\int_{0}^{t}e^{-2\delta s} \|u^{\varepsilon}_{n}(s) \|^{2}_{g}(f(s), u^{\varepsilon}_{n}(s))_{g}ds
				\\& +  2\varepsilon \textbf{E}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}\|\sigma_{n}(s, u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}}ds +  \textbf{E}\int_{0}^{t} e^{-2\delta s}\|\langle 2u^{\varepsilon}_{n}(s) , \sqrt{\varepsilon}\sigma(s, u^{\varepsilon}_{n}(s)) \rangle \|^{2}  ds.
			\end{aligned}
		\end{equation}
		For the second term on the right-hand side of \eqref{eq:1.76}, by Lemma \ref{lem:3.65} and  H\"older inequality, we have
		\begin{equation}
			\label{eq:4.37}
			\begin{aligned}
				4\nu \left| \textbf{E}\int_{0}^{t}e^{- 2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}(u^{\varepsilon}_{n}(s), R_{g}u^{\varepsilon}_{n}(s))_{g} ds \right| &\le 4\nu \frac{\|\nabla g\|_{\infty}}{m_{0}\lambda^{1/2}_{1}}\textbf{E}\int_{0}^{t}e^{- 2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g} \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} ds
				\\& \le \frac{\nu }{4} \textbf{E}\int_{0}^{t}e^{- 2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g} \|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} ds. 
			\end{aligned}
		\end{equation}
		For the third term on the right-hand side of \eqref{eq:1.76}, by H\"older inequality and Young's inequality, we get
		\begin{equation}
			\label{eq:2.30}
			\begin{aligned}
				4\textbf{E}\int_{0}^{t}e^{-2\delta s} \|u^{\varepsilon}_{n}(s) \|^{2}_{g}(f(s), u^{\varepsilon}_{n}(s))_{g}ds  \le 	2 \delta\textbf{E}\int_{0}^{t}e^{-2\delta s} \|u^{\varepsilon}_{n}(s) \|^{4}_{g} ds +   \frac{27}{8 \delta^{3}}              \textbf{E} \int_{0}^{t}e^{-2\delta s}\|f(s)\|^{4}_{V^{*}}ds. 
			\end{aligned}
