		For the fourth and last term on the right-hand side of \eqref{eq:1.76}, by condition (\textbf{A2}) we have
		\begin{equation}
			\label{eq:2.31}
			\begin{aligned}
				&2\varepsilon \textbf{E}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}\|\sigma_{n}(s, u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}}ds +  \textbf{E}\int_{0}^{t} e^{-2\delta s} \|\langle 2u^{\varepsilon}_{n}(s) , \sqrt{\varepsilon}\sigma(s, u^{\varepsilon}_{n}(s)) \rangle \|^{2}ds
				\\& \le  2\varepsilon K\textbf{E}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}\left( 1 + \| u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} \right)ds  + 4\varepsilon \textbf{E}\int_{0}^{t} e^{-2\delta s}\|\sigma_{n}(s, u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds
				\\& \le 6\varepsilon K\textbf{E}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds + 6\varepsilon K\textbf{E}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds.
			\end{aligned}
		\end{equation}
		Combining \eqref{eq:2.30}-\eqref{eq:2.31}, we obtain
		\begin{equation}
			\label{eq:1.77}
			\begin{aligned}
				&\textbf{E}e^{-2\delta t}\|u^{\varepsilon}_{n}(t)\|^{4}_{g} +(4\nu- \frac{\nu}{4} - 6\varepsilon K)\textbf{E} \int_{0}^{t}e^{- \delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} \|u^{\varepsilon}_{n}(s)\|^{2}_{g} ds 
				\\& \le \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} 
				+ \dfrac{27}{8\delta^{3}}\textbf{E}\int_{0}^{t}e^{-2\delta s} \|f(s)\|^{4}_{V^{*}}ds + 6\varepsilon K\textbf{E}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds. 
			\end{aligned}
		\end{equation}
		By \eqref{eq:4.39}, there exists a constant $C_{1} >0$ such that $\textbf{E} \underset{t\in [0,T]}{\sup} \| u^{\varepsilon}_{n}(t)\|^{2}_{g} < C_{1}$. Taking $\varepsilon_{0} < \frac{\nu }{8K}$, we have 
		\begin{equation}
			\label{eq:1.78}
			\begin{aligned}
				& \textbf{E}e^{-2\delta t}\|u^{\varepsilon}_{n}(t)\|^{4}_{g} + 3\nu\textbf{E} \int_{0}^{t}e^{- 2\delta s}\|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}} \|u^{\varepsilon}_{n}(s)\|^{2}_{g} ds 
				\\&  \le \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} 
				+ \dfrac{27}{8\delta^{3}}\textbf{E}\int_{0}^{t}e^{-2\delta s}\|f(s)\|^{4}_{V^{*}}ds +  \dfrac{3\varepsilon K C_{1}}{\delta}
				\\& \le C_{3}\left(\textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} 
				+ \textbf{E}\int_{0}^{t}e^{-2\delta s}\|f(s)\|^{4}_{V^{*}}ds +1  \right),
			\end{aligned}
		\end{equation}
		where $C_{3}$ is a positive constant independent of  $\varepsilon$, $u_{0}$ and $N$. The proof of \eqref{eq:1.75} has been completed.
	\par 
	Finally, we prove \eqref{eq:1.79}. Taking the supremum and expectation in \eqref{eq:1.76}, we obtain that for all  $ t \in [0,T \wedge \tau_{N} ]$, 
	\begin{equation}
		\label{eq:1.80}
		\begin{aligned}
			&\textbf{E} \underset{0 \le t \le T \wedge \tau_{N} }{\sup}e^{-2\delta t}\|u^{\varepsilon}_{n}(t)\|^{4}_{g} +(4\nu - \frac{\nu}{4})\textbf{E}\underset{0 \le t \le T \wedge \tau_{N} }{\sup}\int_{0}^{t} e^{- 2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} \|u^{\varepsilon}_{n}(s)\|^{2}_{g} ds 
			\\& \le \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} + \dfrac{27}{8\delta^{3} } \textbf{E} \underset{0\le t\le T\wedge \tau_{N} }{\sup}\int_{0}^{t}e^{-2\delta s}\|f(s)\|^{4}_{V^{*}}ds
			\\& +  2\varepsilon \textbf{E}\underset{0 \le t \le T\wedge \tau_{N}  }{\sup}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}\|\sigma_{n}(s, u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}}ds 
			\\&+ 4 \varepsilon \textbf{E}\underset{0 \le t \le T\wedge \tau_{N}  }{\sup}\int_{0}^{t} e^{-2\delta s}\|\sigma_{n}(s, u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds  
			\\& +  4 \sqrt{\varepsilon}\textbf{E}\underset{0 \le t \le T\wedge \tau_{N}  }{\sup}\int_{0}^{s}e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}(\sigma_{n}(s,u^{\varepsilon}_{n}(s))dW_{n}(s),  u^{\varepsilon}_{n}(s))_{g}.
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of \eqref{eq:1.80}, using condition (\textbf{A2}) and Burkholder-Davis-Gundy inequality, we have 
	\begin{equation}
		\label{eq:1.81}
		\begin{aligned}
			&4 \sqrt{\varepsilon}\textbf{E}\underset{0 \le t \le T\wedge \tau_{N} }{\sup}\int_{0}^{s}e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}(\sigma_{n}(s,u^{\varepsilon}_{n}(s))dW_{n}(s),  u^{\varepsilon}_{n}(s))_{g} 
			\\& \le 4 \sqrt{\varepsilon} c_{2} \textbf{E}\left(\int_{0}^{T\wedge \tau_{N}} e^{-2\delta s} \|u^{\varepsilon}_{n}(s)\|^{2}_{g} \|\sigma_{n}(s,u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds      \right)^{1/2}
			\\& \le \frac{1}{2}\textbf{E} \underset{0\le t \le T\wedge \tau_{N}}{\sup}e^{-2\delta t} \|u^{\varepsilon}_{n}(t)\|^{4}_{g}  + 2\varepsilon K c^{2}_{2}\textbf{E}\int_{0}^{T\wedge \tau_{N}}e^{-2\delta s} \|u^{\varepsilon}_{n}(s)\|^{2}_{g}\|\sigma_{n}(s,u^{\varepsilon}_{n}(s))\|^{2}_{L_{Q}} ds 
	        \\& \le \frac{1}{2}\textbf{E} \underset{0\le t \le T\wedge \tau_{N}}{\sup}e^{-2\delta t} \|u^{\varepsilon}_{n}(t)\|^{4}_{g} + 2\varepsilon K c^{2}_{2}\textbf{E}\int_{0}^{T\wedge \tau_{N}}e^{-2\delta s} \|u^{\varepsilon}_{n}(s)\|^{2}_{g}\|u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}} ds 
	        \\& +  2\varepsilon K c^{2}_{2}\textbf{E}\int_{0}^{T\wedge \tau_{N}}e^{-2\delta s} \|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds.
		\end{aligned}
	\end{equation}
	Combining \eqref{eq:2.31} - \eqref{eq:1.77} with \eqref{eq:1.81}, we obtain
	\begin{equation}
		\label{eq:1.82}
		\begin{aligned}
			&\frac{1}{2}\textbf{E} \underset{0 \le t \le T\wedge \tau_{N} }{\sup}e^{-2\delta t}\|u^{\varepsilon}_{n}(t)\|^{4}_{g} + \left( 4\nu - \frac{\nu}{4} - 6\varepsilon K - 2\varepsilon K c^{2}_{2} \right)\textbf{E} \int_{0}^{T\wedge \tau_{N}} e^{- 2\delta s} \|u^{\varepsilon}_{n}(t)\|^{2}_{V_{g}} \|u^{\varepsilon}_{n}(s)\|^{2}_{g} ds 
			\\& \le \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} + \dfrac{27}{8\delta^{3}} \textbf{E} \underset{0\le t\le T\wedge \tau_{N}}{\sup}\int_{0}^{t}e^{-2\delta s}\|f(s)\|^{4}_{V^{*}}ds +   (6\varepsilon K + 2\varepsilon K c^{2}_{2})\textbf{E}\underset{0 \le t \le T\wedge \tau_{N} }{\sup}\int_{0}^{t} e^{-2\delta s}\|u^{\varepsilon}_{n}(s)\|^{2}_{g}ds.
		\end{aligned}
	\end{equation}
	From \eqref{eq:1.70}, there exists a constant $C_{1} >0$ such that $\textbf{E} \underset{t\in [0,T]}{\sup} \| u^{\varepsilon}_{n}(t)\|^{2}_{g} < C_{1}$. If $\varepsilon < \frac{11\nu}{K(24+8c^{2}_{2})}$, we obtain that
	\begin{equation}
		\label{eq:1.83}
		\begin{aligned}
			&\textbf{E}\underset{0 \le t \le T}{\sup} e^{-2\delta t}\|u^{\varepsilon}_{n}(t)\|^{4}_{g}  + \nu \textbf{E}\int_{0}^{T}e^{-2\delta t}\| u^{\varepsilon}_{n}(s)\|^{2}_{V_{g}}\|u^{\varepsilon}_{n}(s)\|^{2}_{g} ds 
			\\& \le \textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} +  \dfrac{27}{4\delta^{3}}\textbf{E} \int_{0}^{T} e^{-2\delta t}\|f(t)\|^{4}_{V^{*}} dt + \frac{(6 + 2c^{2}_{2} ) K C_{1} \varepsilon }{\delta} 
			\\& \le C_{4}\left(\textbf{E}\|u^{\varepsilon}_{n}(0)\|^{4}_{g} 
			+ \textbf{E}\int_{0}^{t}e^{-2\delta s}\|f(s)\|^{4}_{V^{*}}ds +1  \right),
		\end{aligned}
	\end{equation}
	where $C_{4}$ is a positive constant independent of $\varepsilon$, $u_{0}$ and $N$. The proof of \eqref{eq:1.79} has been completed.

