\label{thm:1.8}
		Suppose  $f \in L^{4}(0, T; V^{*}_{g})$, (\textbf{A1})--(\textbf{A3}) hold and $\mathbf{E}\,\|u_{0}\|^{4}_{g } < \infty$, then  there exists $\varepsilon_{0} = \min\{\frac{\nu}{8K}, \frac{7\nu}{8K(1+2c^{2}_{2})},\frac{11\nu }{8K(3+ c^{2}_{2})}\}$  such that for every $T> 0$, $ 0< \varepsilon < \varepsilon_{0}$,  there exists a probabilistically strong solution of the following stochastic $g$-Navier--Stokes equation:
		\begin{equation}
			\label{eq:1.23}
		du^{\varepsilon}+(\nu A_{g}u^{\varepsilon} + B_{g}(u^{\varepsilon}, u^{\varepsilon}) + \nu R_{g}u^{\varepsilon})dt = f(t)dt + \sqrt{\varepsilon}\sigma(t,u^{\varepsilon})dW(t)
		\end{equation}
		in $L^{2}(\Omega : C(0, T ; H_{g} )) \cap L^{2}(\Omega \times(0, T ); V_{g} )$. Meanwhile, the solution is pathwise unique.

Let $\Omega_{T} := \Omega \times (0,T)$. Using the a priori estimates given in the above Proposition  \ref{prop:1.22}, it follows from the Banach-Alaoglu theorem that along a subsequence, the Galerkin approximations $\{u_{n}\}$ have the following convergences:
		\[
		u_{n} \to u \quad weakly \,\, in \,\, L^{2}(\Omega_{T}, V_{g}),
		\]
		\[
		u_{n} \to u \quad weakly \,\, star\,\,  in \,\,  L^{4}(\Omega, L^{\infty}(0,T; H_{g})),
		\]
		and 
		\[
		u_{n}(T) \to \eta \quad weakly \,\, in \,\, L^{2}(\Omega_{T}, H_{g}).
		\]
		Recall that $F(u) := -\nu A_{g}u - B_{g}(u,u)-\nu R_{g}u$. Since $F(u_{n})$ is bounded in $L^{2}(\Omega_{T} , V^{*}_{g})$,
		\[
		F(u_{n})\to F_{0} \quad weakly \,\,  in \,\, L^{2}(\Omega_{T} , V^{*}_{g}),
		\]
		Since $\sigma$ satisfies the linear growth condition (\textbf{A2}) and $u_{n}$ is uniformly bounded in $L^{2}(0, T ; V_{g} )$, we may extract a subsequence such that
		\[
		\sigma_{n}(\cdot, u_{n}) \to  S \quad  weakly\,\, in \,\, L^{2}(\Omega_{T}, L_{Q}(H_{0,g};H_{g})).
		\]
		\par 
		Because $u_n$ and $F(u_n)$ converge only weakly, the nonlinear limit cannot be identified by passing directly to the limit in the differential equation. Then, by setting $t \in [0, T]$ to $0$ outside this range, the equation \eqref{eq:1.20} is extended to the open interval $(-\delta, T + \delta)$ with $\delta > 0$. Let $\phi(t)$ be a function in $H^{1}_{g}(-\delta, T + \delta)$ with $\phi(0) = 1$. Define for all integers $j \ge 1, e _{j }(t) = \phi(t)e_{ j}$ where ${e_{ j }}$ is the fixed orthonormal sequence for $H_{g}$.
		\par
		Since $e_{j}(t)$ is a deterministic function, we regard it as a finite variation process and set $Y(t) = (u^{\varepsilon}_{n}(t), e_{j}(t))$. Using It\^o formula, we can obtain
		\begin{equation}
			\label{eq:1.24}
			\begin{aligned}
				(u_{n}(T), e_{j}(T))_{g} &= (u_{n}(0), e_{j})_{g} + \int_{0}^{T} \left( u_{n}(s), \dfrac{de_{j}(s)}{ds} \right)_{g}ds + \int_{0}^{T} (F(u_{n}(s)), e_{j}(s))_{g}ds 
				\\& + \int_{0}^{T} (f(s), e_{j}(s))_{g}ds +\sqrt{\varepsilon}\int_{0}^{T}(\sigma(s,u_{n}(s))dW_{n}(s), e_{j}(s)).
