			\int_{0}^{T} (F_{n}( u_{n}(s)), e_{j}(s))_{g} \to \int_{0}^{T} (F_{0}, e_{j}(s))_{g}ds, \quad as \,\, n \to \infty \,\, for\,\, each\,\, j.
		\end{equation}
		Taking the limit of each term in \eqref{eq:1.24}, we obtain
		\begin{equation}
			\label{eq:1.28}
			\begin{aligned}
			(\eta, e_{j})_{g}\phi(T) &= (u_{0}, e_{j})_{g} + \int_{0}^{T} (F_{0}, e_{j})_{g}\phi(s)ds + \int_{0}^{T} \left( u(s), \dfrac{de_{j}(s)}{ds} \right)_{g}ds 
			\\& + \int_{0}^{T} (f(s), e_{j}(s))_{g}ds + \sqrt{\varepsilon}\int_{0}^{T} \phi(s)(S(s)dW(s), e_{j})_{g}.
			\end{aligned}
		\end{equation}
		Choose the approximating sequence so that its derivative converges to $\delta_{t}$ in the distributional sense. Thus, for any $\psi \in C([0,T]; H_{g})$, we have
		\begin{equation}
			\label{eq:1.29}
			\underset{k \to \infty}{\rm{lim}} \int_{0}^{T} \phi'_{k}(s) \psi(s)ds  = -\underset{k \to \infty}{\rm{lim}} \int_{0}^{T} \phi_{k}(s) \psi'(s)ds= -\psi(t).
		\end{equation}
		Choose functions $\{\phi_{k}\}$ such that $\phi_{k} \to  \textbf{1}_{[0,T]}$ and $\phi'_{k} \to \delta_{t}$ weakly as $k \to \infty$. Substituting $\phi_{k}$ for $\phi$ in \eqref{eq:1.28} and then letting $k \to \infty$, we get that
		\begin{equation}
			\label{eq:1.30}
			(u(t), e_{j})_{g} = (u_{0}, e_{j})_{g} + \int_{0}^{T}(F_{0}, e_{j})_{g}ds + \sqrt{\varepsilon}\int_{0}^{T}(S(s)dW(s), e_{j})_{g}.
		\end{equation}
		When $t < T$ with $(u_{T} , e_{ j} )_{g} = (\eta, e_{j})_{g}$ for all $j$, we obtain 
		\begin{equation}
			\label{eq:1.31}
			u(t) = u(0) + \int_{0}^{t}F_{0}(s)ds + \sqrt{\varepsilon}\int_{0}^{t}S(s)dW(s)
		\end{equation}
		with $u(T) = \eta$.
		\par
		Let $v \in L^{\infty}(\Omega_{T}; H_{m})$ for $m \le n$, and  define $r(t) = \frac{27}{\nu^{3}} \int_{0}^{t}\| v(s)\|^{4}_{L^{4}(\mathcal{O})}ds$. 	By using the monotonicity, we get
		\begin{equation}
			\label{eq:1.32}
			\begin{aligned}
			X_{n}(T) &:=  2{\textbf{E}}\int_{0}^{T} e^{-r(s)}(F(u_{n}(s))- F(v(s)), u_{n}(s)-v(s))_{g}ds 
				- {\textbf{E}}\int_{0}^{T} \dfrac{dr(s)}{dt}e^{-r(s)}\| u_{n}(s)-v(s)\|^{2}_{g} ds 
				\\& + {\textbf{E}}\int_{0}^{T}e^{-r(s)} \|\sigma_{n}(s,u_{n}(s)) -\sigma_{n}(s,v(s)) \|^{2}_{L_{Q}}ds
				\\& \le 0.
			\end{aligned}
		\end{equation}
		Write $X_{n}(T)$ = $Y_{n} + Z_{n}$, where
		\begin{equation}
			\label{eq:1.33}
			\begin{aligned}
				Y_{n} &= 2{\textbf{E}}\int_{0}^{T} (F(u_{n}(s)), u_{n}(s))_{g}e^{-r(s)}ds - {\textbf{E}}\int_{0}^{T} \dfrac{dr(s)}{dt}e^{-r(s)}\| u_{n}(s)|^{2}_{g} ds 
				\\& + {\textbf{E}}\int_{0}^{T}e^{-r(s)} \|\sigma_{n}(s,u_{n}(s))\|^{2}_{L_{Q}}ds,
			\end{aligned}
		\end{equation}
		and
		\begin{equation}
			\label{eq:1.34}
			\begin{aligned}
			Z_{n} &= 2{\textbf{E}}\int_{0}^{T} \left( (F(v(s)), v(s))_{g} -(F(v(s)), u_{n}(s))_{g} -(F(u_{n}(s), v(s))_{g}) \right)e^{-r(s)}ds 
			\\& - {\textbf{E}}\int_{0}^{T} \dfrac{dr(s)}{dt}e^{-r(s)} (\| v(s)\|^{2}_{H_{g}} - 2(u_{n}(s),v(s))_{g})ds 
			\\&  +{\textbf{E}}\int_{0}^{T}e^{-r(s)} \{ \|\sigma_{n}(s,v(s))\|^{2}_{L_{Q}} - 2(\sigma_{n}(u_{n}(s)), \sigma_{n}(v(s))_{L_{Q}}) \}ds.
			\end{aligned}
		\end{equation}
		By It\^o formula, we obtain 
		\begin{equation}
			\label{eq:1.35}
			\begin{aligned}
			e^{-r(T)}\|u_{n}(T)\|^{2}_{g} - \|u_{n}(0)\|^{2}_{g} &=  2{\textbf{E}} \int_{0}^{T}e^{-r(s)}(F(u_{n}(s)), u_{n}(s))_{g}ds - {\textbf{E}} \int_{0}^{T}\frac{dr(s)}{dt}e^{-r(s)} \|u_{n}(s)\|^{2}_{g}ds 
			\\&+ {\textbf{E}} \int_{0}^{T}e^{-r(s)}\|\sigma_{n}(s,u_{n}(s))\|^{2}_{L_{Q}}ds + 2{\textbf{E}} \int_{0}^{T}e^{-r(s)}(f(s), u_{n}(s))_{g}ds.	
			\end{aligned}
		\end{equation}
		By the lower-semicontinuity of $\|u_n(T)\|^{2}_{g}$, we obtain 
		\begin{equation}
			\label{eq:1.36}
			\begin{aligned}
			\underset{n\to \infty}{\rm{lim}} \rm{inf}Y_{n} &= {\textbf{E}}e^{-r(T)}\|u_{n}(T)\|^{2}_{g} - \|u_{n}(0)\|^{2}_{g} \ge {\textbf{E}}e^{-r(T)}\|u_{n}(T)\|^{2}_{g} - \|u(0)\|^{2}_{g} 
			\\&=  2{\textbf{E}} \int_{0}^{T}e^{-r(s)}(F(u_{0}(s)), u(s))_{g}ds - {\textbf{E}} \int_{0}^{T}\frac{dr(s)}{dt}e^{-r(s)} \|u(s)\|^{2}_{g}ds 
		\\& + {\textbf{E}} \int_{0}^{T}e^{-r(s)}\|S(s)\|^{2}_{L_{Q}}ds + {\textbf{E}} \int_{0}^{T}e^{-r(s)}(S(s)dW(s), u(s))_{g}.
			\end{aligned}
		\end{equation}
		In \eqref{eq:1.34}, by taking the limit for each term, we obtain
		\begin{equation}
			\label{eq:1.37}
			\begin{aligned}
		\underset{n\to \infty}{\rm{lim}} Z_{n} &= 2{\textbf{E}}\int_{0}^{T} \left[ (F(v(s)), v(s))_{g} -(F(v(s)), u(s))_{g} -(F_{0}(s), v(s))_{g} \right] e^{-r(s)}ds 
		\\& - {\textbf{E}}\int_{0}^{T} \dfrac{dr(s)}{ds}e^{-r(s)} (\| v(s)\|^{2}_{{g}} - 2(u(s),v(s))_{g})ds 
		\\&  + {\textbf{E}}\int_{0}^{T}e^{-r(s)}  \left(\|\sigma(s,v(s))\|^{2}_{L_{Q}} - 2(S(s), \sigma(v(s))_{L_{Q}}) \right)ds.	
			\end{aligned}
		\end{equation}
		The monotonicity condition and $X_{n} = Y_{n} + Z_{n} \le 0$ imply
		\begin{equation}
			\label{eq:1.38}
			\begin{aligned}
				&2{\textbf{E}}\int_{0}^{T} e^{-r(s)}(F_{0}(s) - F(v(s)), u(s) - v(s))_{g} ds  - {\textbf{E}}\int_{0}^{T} \dfrac{dr(s)}{ds}e^{-r(s)} \| u(s) - v(s)\|^{2}_{g}ds 
				\\&+ {\textbf{E}}\int_{0}^{T}e^{-r(s)}\|S(s) - \sigma(s,v(s))\|^{2}_{L_{Q}}ds
				\\& \le \underset{n\to \infty}{\rm{lim}}\rm{inf}\, X_{n} \le 0.
			\end{aligned}
		\end{equation}
		Setting $v = u$ gives $S(s) = \sigma(s, u(s))$. Next, set $v = u - \lambda w$ with $\lambda > 0$ to obtain 
		\begin{equation}
			\label{eq:1.39}
			\begin{aligned}
				&2\lambda{\textbf{E}}\int_{0}^{T} e^{-r(s)}(F_{0}(s) - F(u(s) - \lambda w(s)), w(s))_{g} ds + \lambda^{2}{\textbf{E}}\int_{0}^{T} \dfrac{dr(s)}{ds}e^{-r(s)} \| w(s)\|^{2}_{g}ds
				\\& + \varepsilon L \lambda^{2}\int_{0}^{T}e^{-r(s)}\|w(s)\|^{2}_{V_{g}}  \le 0.	
			\end{aligned}
		\end{equation}
		Dividing by $\lambda$ on both sides of the inequality above, and letting $\lambda \to 0$, we can conclude
		\begin{equation}
			\label{eq:1.40}
			{\textbf{E}}\int_{0}^{T}(F_{0}(s) - F(u(s)), w(s))_{g}ds \le 0.
		\end{equation}
		Since $w$ is arbitrary, $F_{0}$ = $F(u(s))$. Thus the existence of a strong solution has been proved.
		\par
		We next prove pathwise uniqueness. Let $u_{1}$ and $u_{2}$ be two solutions  of the $g$-Navier--Stokes equation  \eqref{eq:1.23}. For $i = 1, 2$, and $N > 0$, define $\tau^{ i}_{ N} := \inf\{t \le T: \|u_{i} (t)\|_{g} \ge N \}$. Set $\tau_{N} = \min\{\tau^{1}  _{N}, \tau^{2}_{N}\}$. By Chebyshev's inequality, we obtain 
		\begin{equation}
			\label{eq:1.41}
			P\{\tau_{N}  < T \} \le P\{\max \{\underset{t\in [0,T]}{\rm{sup}} \|u_{1}(t) \|_{g}, \underset{t\in [0,T]}{\rm{sup}} \|u_{2}(t) \|_{g} \}  \ge N\} \le \dfrac{C}{N^{2}}.
		\end{equation}
		 Thus $\underset{N \to \infty}{\rm{lim}} \tau_{N}= T$ a.s. 
		\par
		By \eqref{eq:1.23} and It\^o formula, we have for $s \in [0, t \wedge \tau_{N}]$,
		\begin{equation}
			\label{eq:1.42}
			\begin{aligned}
		&\| u_{1}( t \wedge \tau_{N} ) - u_{2}( t \wedge \tau_{N} ) \|^{2}_{g} + 2\nu \int_{0}^{t \wedge \tau_{N}} \|u_{1}(s)- u_{2}(s)\|^{2}_{V_{g}}ds 
		\\& + 2\int_{0}^{t \wedge \tau_{N}} (B_{g}(u_{1}(s), u_{1}(s))- B_{g}(u_{2}(s), u_{2}(s)), u_{1}(s)- u_{2}(s))_{g} ds 
		\\& + 2\nu \int_{0}^{t \wedge \tau_{N}} (R_{g}(u_{1}(s)) - R_{g}(u_{2}(s)), u_{1}(s)- u_{2}(s))_{g} ds 
		\\& =    2 \sqrt{\varepsilon} \int_{0}^{t \wedge \tau_{N}} (u_{1}(s)- u_{2}(s), (\sigma(s,u_{1}(s))- \sigma(s,u_{2}(s)))  dW(s))_{g} 
		\\& + \varepsilon \int_{0}^{t \wedge \tau_{N}} \|\sigma(s,u_{1}(s))- \sigma(s,u_{2}(s))\|^{2}_{L_{Q}} ds.
			\end{aligned}
		\end{equation}
		We now estimate the third term on the left-hand side of \eqref{eq:1.42}. By \eqref{eq:2.3} and the bilinearity of $B_{g}$, we have
		\begin{equation}
			\label{eq:1.44}
			\begin{aligned}
			&\left| b_{g}(u_{1}, u_{1}, u_{1} - u_{2}) - b_{g}(u_{2}, u_{2}, u_{1} - u_{2}) \right| 
			\\&\le | b_{g}(u_{1}, u_{1}, u_{1} - u_{2}) - b_{g}(u_{2}, u_{1}, u_{1} - u_{2}) |
			 + |b_{g}(u_{2}, u_{1}, u_{1} - u_{2}) - b_{g}(u_{2}, u_{2}, u_{1} - u_{2})|
			\\& = |b_{g}(u_{1} - u_{2}, u_{1}, u_{1} - u_{2})| + |b_{g}(u_{2}, u_{1} - u_{2}, u_{1} - u_{2})|.
		\end{aligned}
		\end{equation}
		By Ladyzhenskaya inequality and H\"older inequality, we obtain
		\begin{equation}
			\label{eq:1.45}
			\begin{aligned}
			|b_{g}(u_{1}(s) - u_{2}(s), u_{1} ,u_{1}(s) - u_{2}(s) )| & \le \int_{\mathcal{O}}^{}  |u_{1}(s) - u_{2}(s)| |\nabla u_{1}||u_{1}(s) - u_{2}(s)| gdx 
			\\& \le \|u_{1}(s) - u_{2}(s)\|^{2}_{L^{4}}\|\nabla u_{1}\|_{g}
			\\& \le \frac{\sqrt{2M_{0}}}{m_{0}}\|u_{1}(s) - u_{2}(s)\|_{g}\|u_{1}(s) - u_{2}(s)\|_{V_{g}} \|u_{1}\|_{V_{g}}
			\\& \le \frac{15\nu }{8}\|u_{1}(s) - u_{2}(s)\|^{2}_{V_{g}} + \frac{8 M_{0}}{15\nu m^{2}_{0}}\|u_{1}(s) - u_{2}(s)\|^{2}_{{g}} \|u_{1}\|^{2}_{V_{g}}.
			\end{aligned}
		\end{equation}
		For the fourth term on the left-hand side of \eqref{eq:1.42},  by \eqref{eq:2.10}, we get
		\begin{equation}
			\label{eq:1.46}
			\begin{aligned}
		2\nu \int_{0}^{t \wedge \tau_{N}} (R_{g}(u_{1}(s)) -R_{g}(u_{2}(s)), u_{1}(s) - u_{2}(s))_{g}ds  
		& \le 2\nu \int_{0}^{t \wedge \tau_{N}}\frac{\|\nabla g\|_{\infty}}{m_{0}\sqrt{\lambda_{1}}} \|u_{1}(s) - u_{2}(s)\|^{2}_{V_{g}}ds
		\\&\le \frac{\nu}{8} \int_{0}^{t \wedge \tau_{N}} \|u_{1}(s) - u_{2}(s)\|^{2}_{V_{g}}ds.
			\end{aligned}
		\end{equation}
		For the last term on the right-hand side of \eqref{eq:1.42}, by condition (\textbf{A2}), we have 
		\begin{equation}
			\label{eq:1.43}
			\begin{aligned}
			\varepsilon \int_{0}^{t \wedge \tau_{N}} \|\sigma(s,u_{1}(s))- \sigma(s,u_{2}(s))\|^{2}_{L_{Q}} ds  \le \varepsilon L\, \int_{0}^{t \wedge \tau_{N}}  \|u_{1}(s) - u_{2}(s)\|^{2}_{g}ds. 
			\end{aligned}
		\end{equation}
		Substituting \eqref{eq:1.45} - \eqref{eq:1.43} into \eqref{eq:1.42}, and taking the expectation, we obtain
		\begin{equation}
			\label{eq:1.47}
			\begin{aligned}
	 \textbf{E} \| u_{1}( t \wedge \tau_{N} ) - u_{2}( t \wedge \tau_{N} ) \|^{2}_{g} 	\le \textbf{E} \int_{0}^{t \wedge \tau_{N}} \|u_{1}(s) - u_{2}(s)\|^{2}_{g} \left( \frac{8 M_{0}}{15 \nu m^{2}_{0}}\|u_{1} (s) \|^{2}_{V_{g}} + \varepsilon L  \right)ds. 
			\end{aligned}
		\end{equation}
		Finally, using Gronwall inequality we know that
		\begin{equation}
			\label{eq:4.58}
			\begin{aligned}
			\textbf{E} \| u_{1}( t \wedge \tau_{N} ) - u_{2}( t \wedge \tau_{N} ) \|^{2}_{g} = 0.
			\end{aligned}
		\end{equation}
		Taking $N \to \infty$ and applying Fatou’s lemma, the pathwise uniqueness can be proved. This proof is completed.

\label{drfn:1.9}(Large Deviation Principle). 
	The family $\{u^{\varepsilon}\}$ is said to satisfy the LDP in $\mathcal{E}$ with a rate function $I: \mathcal{E} \to [0, \infty]$, if for every Borel subset $A$ of $\mathcal{E}$,
	\begin{equation}
		\label{eq:1.53}
		\begin{aligned}
			- \underset{x\in A^{\circ}}{\inf}\, I(x)  \le \underset{\varepsilon \to 0}{\lim\, \inf} \varepsilon\,  \log\mathbb{P} (u^{\varepsilon} \in A) \le \underset{\varepsilon \to 0}{\lim\, \sup}\,  \varepsilon\,  \log\mathbb{P}(u^{\varepsilon} \in A) \le - \underset{x\in \bar{A}}{\inf}\, I(x),
		\end{aligned}
	\end{equation}
	where $A^{\circ}$ and $\bar{A}$ are the interior and the closure of $A$ in $\mathcal{E}$, respectively.

\label{drfn:1.10}(Laplace principle). The family $\{u^{\varepsilon}\}$ is said to satisfy the Laplace principle in $\mathcal{E}$ with a rate function $I: \mathcal{E} \to [0, \infty]$ if for all bounded and continuous $\phi:  \mathcal{E} \to \mathbb{R}$, 
	\begin{equation}
		\label{eq:1.54}
		\begin{aligned}
			\underset{\varepsilon \to 0}{\lim}\, \varepsilon\, \log \mathbb{E}\left[e^{-\frac{1}{\varepsilon}\phi(u^{\varepsilon})} \right] = -\underset{x\in \mathcal{E}}{\inf}\{\phi(x) + I(x)  \}.
		\end{aligned}
	\end{equation}

\label{prop:1.11}
	Under (\textbf{H1})-(\textbf{H2}), the family $\{u^{\varepsilon}\}$, given by \eqref{eq:1.52}, satisfies the Laplace principle in $\mathcal{E}$ with rate function $I$ defined by, for every $x \in \mathcal{E}$,
	\begin{equation}
		\label{eq:1.55}
		\begin{aligned}
		I(x) = \inf \left\{\frac{1}{2}   \int_{0}^{T}\| h(t)\|^{2}_{0}dt: h\in L^{2}(0,T; H_{0,g})  \quad such\,\, that \quad  \mathcal{G}^{\circ} ( \int_{0}^{.}h(t)dt) =x \right\},
		\end{aligned}
	\end{equation}
	where the infimum over an empty set is taken to be $\infty$.

\label{lem:1.13}
	Suppose that $f \in L^{4}(0,T; V^{*}_{g})$  and (\textbf{A1})-(\textbf{A3}) hold. Then for every $v\in L^{2}(0,T; H_{0,g})$ problem  \eqref{eq:1.56}  has a unique solution $u_{v} \in C([0, T], H_{g}) \cap L^{2}( 0,T; V_{g})$.\par 
	Moreover, for any $\|u_{0}\|_{{g}} \vee \|u_{0,1}\|_{{g}} \vee \|u_{0,2}\|_{{g}} \le R_{1}$ and $\|v\|_{L^{2}(0,T; H_{0,g})}$ $ \vee \|v_{1}\|_{L^{2}(0,T; H_{0,g})} \vee \|v_{2}\|_{L^{2}(0,T; H_{0,g})}$ $\le R_{2}$, the solutions  $u_{v}, u_{v_{1}}$, and $u_{v_{2}}$ of \eqref{eq:1.56} with initial data $u_{0}, u_{0,1}$, and $u_{0,2}$, respectively, satisfy for all $t \in [0, T]$,
	\begin{equation}
		\label{eq:1.84}
		\begin{aligned}
		\| u_{v}(t)\|^{2}_{g} + \nu \int_{0}^{t}\| u_{v}(s)\|^{2}_{V_{g}} ds \le C_{1}, 
		\end{aligned}
	\end{equation}
	\begin{equation}
		\label{eq:1.85}
		\begin{aligned}
			\| u_{v_{1}}(t)  - u_{v_{2}}(t) \|^{2}_{g} + \nu \int_{0}^{t}\| u_{v_{1}}(t)  - u_{v_{2}}(t) \|^{2}_{V_{g}} ds  \le C_{1} \left(\|u_{0,1} - u_{0,2}\|^{2}_{g} + \|v_{1} - v_{2}\|^{2}_{L^{2}(0,T; H_{0,g})} \right), 
		\end{aligned}
	\end{equation}
	where $R_{1}, R_{2} > 0$ are given, and $C_{1} > 0$ depends on $R_{1}, R_{2}$, and $T$.

Under conditions (\textbf{A1})--(\textbf{A3}), by the argument of [\cite{ref Da Prato3}, Theorem 7.10], one can show that for every $T > 0$, $v \in L^{2}(0, T; H_{0,g})$ and $u_{0} \in H_{g}$, problem \eqref{eq:1.56}  has a unique solution $u_{v}\in C([0, T], H_{g}) \cap L^{2}( 0,T; V_{g})$. 
\par 
Next, we prove \eqref{eq:1.84}. By \eqref{eq:2.10}, \eqref{eq:1.56}, we get
\begin{equation}
	\label{eq:1.86}
	\begin{aligned}
	d\| u_{v}(t)\|^{2}_{g} + 2\nu \|u_{v}(t)\|^{2}_{V_{g}}dt \le \frac{\nu }{8} \|u_{v}(t)\|^{2}_{V_{g}}dt + 2(f(t), u_{v}(t))_{g} dt
	 +   2(\sigma(t,  u_{v}(t))v(t),  u_{v}(t))_{g}dt.
	\end{aligned}
\end{equation}
For the second term on the right-hand side of \eqref{eq:1.86}, by H\"older inequality, we obtain
\begin{equation}
	\label{eq:4.60}
	\begin{aligned}
	2\left|(f(t), u_{v}(t))_{g}  \right| \le \dfrac{\nu }{8}\|u_{v}(t)\|^{2}_{V_{g}} + \frac{8}{\nu} \|(f(t)\|^{2}_{V^{*}}. 
	\end{aligned}
\end{equation}
For the last term on the right-hand side of \eqref{eq:1.86}, by (\textbf{A2}) and  Young's inequality, we find
\begin{equation}
	\label{eq:1.87}
	\begin{aligned}
	2(\sigma(t,  u_{v}(t))v(t),  u_{v}(t))_{g} &= 2\int_{\mathcal{O}}^{}\sigma(t,  u_{v}(t))v(t) \cdot u_{v}(t)\,gdx 
	\\& \le \frac{3\nu }{4KR_{2}}\|\sigma(t,  u_{v}(t))\|^{2}_{L_{Q}} \|v(t)\|^{2}_{L^{2}(0,T; H_{0,g})} + \frac{4KR_{2}}{3\nu }\|u_{v}(t)\|^{2}_{g}
	\\& \le \frac{3\nu }{4}\|u_{v}(t)\|^{2}_{V_{g}} + \frac{3\nu }{4} + \frac{4KR_{2}}{3\nu }\|u_{v}(t)\|^{2}_{{g}}. 
	\end{aligned}
\end{equation}
Combining \eqref{eq:4.60}- \eqref{eq:1.87}, we get for any $t \in [0,T]$,
\begin{equation}
	\label{eq:1.88}
	\begin{aligned}
		d\| u_{v}(t)\|^{2}_{g}  + \nu \|u_{v}(t)\|^{2}_{V_{g}}dt \le \frac{4KR_{2}}{3\nu }\|u_{v}(t)\|^{2}_{{g}}dt + \frac{3\nu }{4} + \dfrac{8}{\nu}\|f(t)\|^{2}_{V^{*}}dt.
	\end{aligned}
\end{equation}
From \eqref{eq:1.88} and Gronwall  inequality, it follows that for any $t \in [0,T]$,
\begin{equation}
	\label{eq:1.89}
	\begin{aligned}
		\| u_{v}(t)\|^{2}_{g} \le \|u_{0}\|^{2}_{g}e^{\frac{4KR_{2}T}{3\nu }} + e^{\frac{4KR_{2}T}{3\nu }} \int_{0}^{T} \left(  \dfrac{8}{ \nu} \|f(s)\|^{2}_{V^{*}} + \frac{3\nu}{4} \right)ds.
	\end{aligned}
\end{equation}
\par 
By \eqref{eq:1.89} we infer that for every $R_{1} > 0$ and $R_{2} > 0$ , there exists $\textbf{c}_{1} = \textbf{c}_{1}(R_{2}, K, T,\nu  ) > 0$ such that for any $u_{0} \in H_{g}$ with $\|u_{0}\|_{g} \le R_{1}$ and any $v \in L^{2}(0, T ; H_{0,g})$ with $\|v\|_{L^{2}(0, T ; H_{0,g})} \le  R_{2}$, the solution $u_{v}$ satisfies, for all $t \in [0, T]$,
\begin{equation}
	\label{eq:4.40}
	\begin{aligned}
		\| u_{v}(t)\|^{2}_{g} \le \textbf{c}_{1}, \forall t\in[0,T].
	\end{aligned}
\end{equation}
\par 
Integrating \eqref{eq:1.88} over $[0, T ]$ and using \eqref{eq:4.40}, we find a constant $\textbf{c}_{2} = \textbf{c}_{2}(R_{1}, R_{2}, K, T,\nu) > 0$ such that for all $u_{0}\in H_{g}$ with $\|u_{0}\|_{g} \le R_{1}$ and any $v \in L^{2}(0, T ; H_{0,g})$ with $\|v\|_{L^{2}(0, T ; H_{0,g})} \le  R_{2}$, 
\begin{equation}
	\label{eq:4.41}
	\begin{aligned}
	\nu \int_{0}^{t}\|u_{v}(s)\|^{2}_{V_{g}}ds \le \textbf{c}_{2}. 
	\end{aligned}
\end{equation}
Then \eqref{eq:1.84} follows from \eqref{eq:4.40}-\eqref{eq:4.41}.
\par
Next, we prove \eqref{eq:1.85}. Let $u_{v_{1}}$ and $u_{v_{2}}$ be the solutions of \eqref{eq:1.56} with initial data $u_{0,1}$ and $u_{0,2}$, respectively. By \eqref{eq:1.84}, we find that if $ \|u_{0,1}\|_{{g}} \vee \|u_{0,2}\|_{{g}} \le R_{1}$ and $\| v_{1}\|_{L^{2}(0,T;H_{0,g})} \vee \| v_{2}\|_{L^{2}(0,T;H_{0,g})} \le  R_{2}$, then
\begin{equation}
	\label{eq:1.91}
	\begin{aligned}
		\| u_{v_{1}}(t)\|_{g}  + \| u_{v_{2}}(t)\|_{g} \le 2 C_{1},\,\, \forall t\in[0,T],
	\end{aligned}
\end{equation}
where $C_{1} = C_{1}(R_{1}, R_{2}, T) > 0$. Similarly, by \eqref{eq:2.10}, \eqref{eq:1.56}, we obtain
\begin{equation}
	\label{eq:1.92}
	\begin{aligned}
		& d\| u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{g} + 2\nu \|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{V_{g}}dt 
		\\& + (B_{g}(u_{v_{1}}(t), u_{v_{1}}(t)) -B_{g}(u_{v_{2}}(t), u_{v_{2}}(t)), u_{v_{1}}(t) - u_{v_{2}}(t))_{g}dt \\&\le \dfrac{\nu }{8} \|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{V_{g}} + 2(\sigma(t, u_{v_{1}}(t))v_{1}(t)-\sigma(t, u_{v_{2}}(t))v_{2}(t),  u_{v_{1}}(t) - u_{v_{2}}(t))_{g}dt.
	\end{aligned}
\end{equation}
For the third term on the left-hand side of \eqref{eq:1.92}, by \eqref{eq:2.3}, we get
\begin{equation}
	\label{eq:2.50}
	\begin{aligned}
    &\left| (B_{g}(u_{v_{1}}(t), u_{v_{1}}(t)) -B_{g}(u_{v_{2}}(t), u_{v_{2}}(t)), u_{v_{1}}(t) - u_{v_{2}}(t))_{g} \right|
    \\& \le  \left|b_{g}(u_{v_{1}}(t), u_{v_{1}}(t), u_{v_{1}}(t) - u_{v_{2}}(t))  -b_{g}(u_{v_{1}}(t), u_{v_{1}}(t), u_{v_{2}}(t) - u_{v_{2}}(t))\right|
    \\& + \left|b_{g}(u_{v_{1}}(t), u_{v_{2}}(t), u_{v_{1}}(t) - u_{v_{2}}(t))  -b_{g}(u_{v_{2}}(t), u_{v_{2}}(t), u_{v_{1}}(t) - u_{v_{2}}(t))\right|
    \\& \le \left|b_{g}(u_{v_{1}}(t), u_{v_{1}}(t)- u_{v_{2}}(t)) , u_{v_{1}}(t) - u_{v_{2}}(t)) \right| +  \left|b_{g}(u_{v_{1}}(t) - u_{v_{2}}(t), u_{v_{2}}(t) , u_{v_{1}}(t) - u_{v_{2}}(t)) \right|
    \\& = \left|b_{g}(u_{v_{1}}(t) - u_{v_{2}}(t), u_{v_{2}}(t) , u_{v_{1}}(t) - u_{v_{2}}(t)) \right|.
	\end{aligned}
\end{equation}
By Ladyzhenskaya inequality and H\"older inequality, we obtain
\begin{equation}
	\label{eq:2.51}
	\begin{aligned}
	& \left|b_{g}(u_{v_{1}}(t) - u_{v_{2}}(t), u_{v_{2}}(t) , u_{v_{1}}(t) - u_{v_{2}}(t)) \right| 
	\\& \le \|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{L^{4}}\|\nabla u_{v_{2}}(t)\|_{g}. 
	\\& \le \frac{\sqrt{2 M_{0}}}{m_{0}} \|u_{v_{1}}(t) - u_{v_{2}}(t)\|_{g}\|u_{v_{1}}(t) - u_{v_{2}}(t)\|_{V_{g}}\|\nabla u_{v_{2}}(t)\|_{g}
	\\& \le \frac{7\nu}{8} \|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{V_{g}} + \frac{8M_{0}}{7\nu m^{2}_{0}}\|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{g} \| u_{v_{2}}(t)\|^{2}_{V_{g}}. 
	\end{aligned}
\end{equation}
For the last term on the right-hand side of \eqref{eq:1.92}, by (\textbf{A2}) and (\textbf{A3}) we get for any $t\in[0,T]$,
\begin{equation}
	\label{eq:1.93}
	\begin{aligned}
		& 2\left|(\sigma(t, u_{v_{1}}(t))v_{1}(t)-\sigma(t, u_{v_{2}}(t))v_{2}(t),  u_{v_{1}}(t) - u_{v_{2}}(t))_{g}\right|
		\\& =    2 \left|(\sigma(t, u_{v_{1}}(t))v_{1}(t)-\sigma(t, u_{v_{2}}(t))v_{1}(t),  u_{v_{1}}(t) - u_{v_{2}}(t))_{g}\right| 
		\\& + 2 \left| (\sigma(t, u_{v_{2}}(t))v_{1}(t)-\sigma(t, u_{v_{2}}(t))v_{2}(t),  u_{v_{1}}(t) - u_{v_{2}}(t))_{g}\right|
		\\& \le 2\| \sigma(t, u_{v_{1}}(t))-\sigma(t, u_{v_{2}}(t))\|_{L_{Q}}\|v_{1}(t)\|_{L^{2}(0,T; H_{0,g})} \|u_{v_{1}}(t) - u_{v_{2}}(t)\|_{g} 
		\\&+ 2\| \sigma(t, u_{v_{2}}(t))\|_{L_{Q}}\|v_{1}(t) - v_{2}(t)\|_{L^{2}(0,T ; H_{0,g})} \|u_{v_{1}}(t) - u_{v_{2}}(t)\|_{g}
		\\& \le 2\sqrt{L}\|v_{1}(t)\|_{L^{2}(0,T ; H_{0,g})} \|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{g} + c_{3} \|v_{1}(t) - v_{2}(t)\|^{2}_{L^{2}(0,T; H_{0,g})} 
		\\& + c_{3}\|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{g},
	\end{aligned}
\end{equation}
where $c_{3} = \sqrt{K( 1+ C^{2}_{1})}$. Therefore, by \eqref{eq:2.50}- \eqref{eq:1.93}, we find that for any $t \in [0,T]$, 
\begin{equation}
	\label{eq:1.94}
	\begin{aligned}
		&d\| u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{g} + \nu \int_{0}^{t}\| u_{v_{1}}(s)  - u_{v_{2}}(s) \|^{2}_{V_{g}} ds
		\\& \le  \left( 2\sqrt{L}\|v_{1}(t)\|_{L^{2}(0,T ; H_{0,g})} + \frac{8M_{0} C_{1}}{7 \nu m^{2}_{0}} + c_{3} \right) \|u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{g} + c_{3}\|v_{1}(t) - v_{2}(t)\|^{2}_{L^{2}(0,t ; H_{0,g})}.
	\end{aligned}
\end{equation}
From \eqref{eq:1.94} and Gronwall’s inequality, we obtain that for any $t \in [0,T]$, 
\begin{equation}
	\label{eq:1.95}
	\begin{aligned}
		 \| u_{v_{1}}(t) - u_{v_{2}}(t)\|^{2}_{g}   
		 & \le  e^{\int_{0}^{T}\left( 2 \sqrt{L}\|v_{1}(s)\|_{L^{2}(0,t ; H_{0,g})} + \frac{8M_{0} C_{1}}{7 \nu m^{2}_{0}}  + c_{3}  \right)ds} \|u_{0,1} - u_{0,2}\|^{2}_{g} 
		 \\&+ c_{3}e^{\int_{0}^{T}\left( 2 \sqrt{L}\|v_{1}(s)\|_{L^{2}(0,t ; H_{0,g})} +\frac{8M_{0} C_{1}}{7 \nu m^{2}_{0}} +c_{3}  \right)ds}\int_{0}^{t}\|v_{1}(s) - v_{2}(s)\|^{2}_{L^{2}(0,t ; H_{0,g})}ds
		 \\& \le \textbf{c}_{3} \left(\|u_{0,1} - u_{0,2}\|^{2}_{g} + \|v_{1} - v_{2}\|^{2}_{L^{2}(0,T; H_{0,g})} \right), 
	\end{aligned}
\end{equation}
where $\textbf{c}_{3} = \textbf{c}_{3}(R_{1}, R_{2},\nu, T,K) > 0$. By \eqref{eq:1.94} - \eqref{eq:1.95}, we get
\begin{equation}
	\label{eq:4.42}
	\begin{aligned}
	\nu \int_{0}^{t}\| u_{v_{1}}(s)  - u_{v_{2}}(s) \|^{2}_{V_{g}} ds \le \textbf{c}_{4} \left(\|u_{0,1} - u_{0,2}\|^{2}_{g} + \|v_{1} - v_{2}\|^{2}_{L^{2}(0,T; H_{0,g})} \right),
	\end{aligned}
\end{equation}
where $\textbf{c}_{4} = \textbf{c}_{4}(R_{1}, R_{2},\nu, T,K) > 0$, which along with \eqref{eq:1.95} yields \eqref{eq:1.85}.

\label{lem:3.57}
	Suppose that (\textbf{A1})--(\textbf{A3}) hold. Then for every $\varepsilon'> 0$, $T > 0$, $R > 0$, and $u_{0} \in H_{g}$, there exists $K^{*} = K^{*}(\alpha, \lambda_{1}, T, u_{0}, R_{3}, \varepsilon') > 0$ with $\alpha < \frac{\nu \lambda_{1} - 2\sqrt{\varepsilon L}R_{3}M_{0}}{\nu }$ such that for all $v \in L^{2}(0, T ; H_{0,g})$ with $\| v \|_{L^{2}(0, T ; H_{0,g})} \le R_{3}$, the solution $u_{v}$ of \eqref{eq:1.56} satisfies, for all $k \ge K^{*}$ and $t \in [0,T]$,
	\begin{equation}
		\label{eq:1.96}
		\begin{aligned}
		\int_{|x|\ge k}^{} |u_{v}(t,x)|^{2} dx  < \varepsilon'. 
		\end{aligned}
	\end{equation}

Let $\varrho : \mathbb{R}^{n}  \to  [0, 1]$ be a smooth function satisfying
	\begin{equation}
		\label{eq:1.97}
		\begin{aligned}
			\varrho(x) = 0  \quad for \quad  |x| \le \dfrac{1}{2}, \quad and \quad \varrho(x) = 1 \quad for \quad |x| \ge  1.
		\end{aligned}
	\end{equation}
	Note that there exists $C > 0$ such that $|\varrho'(s)|+|\varrho''(s)|\le C$ for all $s \in \mathbb{R}$. Set $\varrho_{k}(x) =  \varrho(\frac{x}{k})$ for $k \in \mathbb{N}$. Multiplying \eqref{eq:3.71} by $- \varrho^{2}_{k}\tilde{u}_{v}$ and integrating this result over $\mathcal{O}$, we obtain
	\begin{equation}
		\label{eq:1.98}
		\begin{aligned}
		-(\partial_{t}  \mathcal{L}_{g}\tilde{u}_{v}, \varrho^{2}_{k}\tilde{u}_{v})_{g} = - (\nu \Delta \mathcal{L}_{g}\tilde{u}_{v}, \varrho^{2}_{k}\tilde{u}_{v})_{g} +  (\tilde{B_{g}}(\tilde{u}_{v}, \tilde{u}_{v}),\varrho^{2}_{k}\tilde{u}_{v} )_{g}- (\sqrt{\varepsilon} \tilde{\sigma}(t,u_{v})v(t),\varrho^{2}_{k}\tilde{u}_{v})_{g}.
		\end{aligned}
	\end{equation}
	For the left-hand side of \eqref{eq:1.98} we have
	\begin{equation}
		\label{eq:3.90}
		\begin{aligned}
			-(\partial_{t}  \mathcal{L}_{g}\tilde{u}_{v}, \varrho^{2}_{k}\tilde{u}_{v})_{g} &= - \int_{\mathcal{O}}^{}\partial_{t} (\mathcal{L}_{g}\tilde{u}_{v})(\varrho^{2}_{k}\tilde{u}_{v}) gdx = -\int_{\mathcal{O}}^{}\partial_{t} (\frac{1}{g} \Delta \tilde{u}_{v} + \nabla(\frac{1}{g})\cdot \tilde{u}_{v} )(\varrho^{2}_{k}\tilde{u}_{v}) gdx 
			\\&= \int_{\mathcal{O}}^{} \nabla (\partial_{t}\tilde{u}_{v})\cdot (\nabla \varrho^{2}_{k}\tilde{u}_{v})dx - \int_{\mathcal{O}}^{} \partial_{t}(\nabla(\frac{1}{g})\cdot\nabla \tilde{u}_{v})\cdot (\varrho^{2}_{k}\tilde{u}_{v}) gdx
			\\& = \int_{\mathcal{O}}^{} \nabla (\partial_{t}\tilde{u}_{v})\cdot ( \varrho^{2}_{k}\nabla\tilde{u}_{v}  + 2\varrho_{k}\tilde{u}_{v}\nabla \varrho_{k} )dx + \int_{\mathcal{O}}^{} \partial_{t}((\frac{\nabla g}{g^{2}})\cdot\nabla \tilde{u}_{v})\cdot (\varrho^{2}_{k}\tilde{u}_{v}) gdx 
			\\& \ge \frac{1}{2}\frac{d}{dt} \int_{\mathcal{O}}^{}\varrho^{2}_{k}|\nabla \tilde{u}_{v}|^{2}dx - \frac{2}{k} \|\nabla \tilde{u}_{v_{t}}\| \|\tilde{u}_{v}\| - \frac{1}{m_{0}} \|\nabla \tilde{u}_{v_{t}}\| \|\tilde{u}_{v}\| \|\nabla g\|_{\infty}.
		\end{aligned}
	\end{equation}
	For the first term on the right-hand side of \eqref{eq:1.98}, by H\"older inequality we have
	\begin{equation}
		\label{eq:3.91}
		\begin{aligned}
			-(\nu \Delta \mathcal{L}_{g}\tilde{u}_{v}, \varrho^{2}_{k}\tilde{u}_{v})_{g} &= -\nu \int_{\mathcal{O}}^{} \mathcal{L}_{g} \tilde{u}_{v}\cdot (\varrho^{2}_{k} \Delta\tilde{u}_{v} + \tilde{u}_{v}(\Delta \varrho^{2}_{k}) + 2\nabla \varrho^{2}_{k}\cdot \nabla \tilde{u}_{v} ) g dx
			\\& \le -\nu \|\varrho_{k} \Delta \tilde{u}_{v}\|^{2}  + \frac{\nu }{m_{0}} \|\varrho_{k} \nabla \tilde{u}_{v}\|\|\nabla g\|_{\infty}\|\| \varrho_{k} \Delta \tilde{u}_{v}\|^{2} - \frac{\nu}{k} \|\Delta \tilde{u}_{v}\|\|\tilde{u}_{v}\| 
			\\& + \frac{\nu}{k^{2}m_{0}}\|\nabla \tilde{u}_{v}\|\|\tilde{u}_{v}\|\|\nabla g\|_{\infty} - \frac{4\nu }{k}\|\Delta \tilde{u}_{v}\|\| \varrho_{k} \nabla \tilde{u}_{v}\| + \frac{4\nu}{m_{0}k} \|\nabla \tilde{u}_{v}\|\|\varrho_{k}\nabla \tilde{u}_{v}\|\|\nabla g\|_{\infty}
			\\& \le - \frac{\nu }{2} \|\varrho_{k} \Delta \tilde{u}_{v}\|^{2} + \frac{\nu^{2}\lambda_{1} }{512} \|\varrho_{k} \nabla \tilde{u}_{v}\|^{2} + \frac{2\nu C}{k^{2}}\|\Delta \tilde{u}_{v}\|\|\tilde{u}_{v}\|
			\\& + \frac{\nu \lambda^{1/2}_{1}}{16k^{2} m_{0}} \|\nabla \tilde{u}_{v}\|\|\tilde{u}_{v}\| + \frac{4\nu}{k}\|\Delta \tilde{u}_{v}\|\|\nabla \tilde{u}_{v}\| + \frac{\nu \lambda_{1}}{k}\|\nabla \tilde{u}_{v}\|^{2}.
		\end{aligned}
	\end{equation}
	Using (\cite{ref Wang. B4} , Lemma 3.1) we obtain
	\begin{equation}
		\label{eq:4.82}
		\begin{aligned}
			\lambda_{1} \|\varrho_{k} \nabla \tilde{u}\|^{2} &\le \|\varrho_{k} \Delta \tilde{u}\|^{2} + \dfrac{c^{2}_{3}}{k^{2}}\|\tilde{u}\|_{H^{1}(\mathcal{O})}	 + \frac{2c_{3}}{k} \|\varrho_{k} \Delta \tilde{u}\|\|\tilde{u}\|_{H^{1}(\mathcal{O})}
			\\& \le \frac{2\lambda_{1}}{2\lambda_{1} -\alpha}\|\varrho_{k} \Delta \tilde{u}\|^{2}  + \dfrac{2\lambda_{1} c^{2}_{3}}{\alpha k^{2}}\|\tilde{u}\|_{H^{1}(\mathcal{O})}.
		\end{aligned}
	\end{equation}
	By \eqref{eq:3.91} and \eqref{eq:4.82} we obtain
	\begin{equation}
		\label{eq:3.92}
		\begin{aligned}
			-(\nu \Delta \mathcal{L}_{g}\tilde{u}_{v}, \varrho^{2}_{k}\tilde{u}_{v})_{g} \le  \frac{\nu}{2}(\frac{1}{2}\alpha - \lambda_{1})\|\varrho_{k} \nabla \tilde{u}_{v}\|^{2} +  \frac{\nu \lambda^{1/2}_{1}c_{4}}{k} \|\Delta\tilde{u}_{v}\|^{2}  ,
		\end{aligned}
	\end{equation}
	where $c_{4} =c_{4}(C, m_{0}) > 0$ is independent of $k$. \par 
	For the second term on the right-hand side of \eqref{eq:1.98}, by the divergence formula, Ladyzhenskaya, H\"older, and Young's inequalities we have
	\begin{equation}
		\label{eq:3.93}
		\begin{aligned}
			 (\tilde{B}_{g}(\tilde{u}_{v},\tilde{u}_{v}), \varrho^{2}_{k}\tilde{u}_{v} )_{g} &= \int_{\mathcal{O}}^{}\left( -\partial_{ x_{2}}[ \frac{1}{g}\partial_{ x_{1}}\tilde{u}_{v} (\mathcal{L}_{g}\tilde{u}_{v})] +\partial_{ x_{1}}[ \frac{1}{g}\partial_{ x_{2}}\tilde{u}_{v} (\mathcal{L}_{g}\tilde{u}_{v})]   \right)\varrho^{2}_{k}\tilde{u}_{v}gdx
			\\& = - \int_{\mathcal{O}}^{} \frac{1}{g} \partial_{ x_{2}}\tilde{u}_{v}\cdot \Delta \tilde{u}_{v}\cdot \tilde{u}_{v} \cdot \partial_{ x_{1}}(\varrho^{2}_{k})dx  - \int_{\mathcal{O}}^{} \nabla(\frac{1}{g})  \partial_{ x_{2}} \tilde{u}_{v}\cdot \nabla\tilde{u}_{v}\cdot \tilde{u}_{v} \cdot \partial_{ x_{1}}(\varrho^{2}_{k})dx
			\\& \le \frac{2C}{m_{0}k} \|\Delta \tilde{u}_{v}\|\|\tilde{u}_{v}\|_{L^{4}}\|\partial _{x_{2}}\tilde{u}_{v}\|_{L^{4}(\mathcal{O})} + \frac{\lambda^{1/2}_{1} C }{8m_{0}k}\|\nabla \tilde{u}_{v}\|\|\tilde{u}_{v}\|_{L^{4}(\mathcal{O})}\|\partial _{x_{2}}\tilde{u}_{v}\|_{L^{4}(\mathcal{O})}
			\\& \le \frac{2\sqrt{2}C}{m_{0}k \lambda_{1}} \|\Delta \tilde{u}_{v}\|^{3/2} \|\nabla \tilde{u}_{v}\|^{3/2} + \frac{2^{1/4}}{8m_{0}k} \|\nabla \tilde{u}_{v}\|^{5/2}\|\Delta \tilde{u}_{v}\|^{1/2}
			\\& \le \frac{ c_{5}}{m_{0}k} \left(2\|\Delta \tilde{u}_{v}\|^{2} +  \|\nabla \tilde{u}_{v}\|^{6}  + \|\nabla \tilde{u}_{v}\|^{10/3}   \right)
			\\& \le \frac{ c_{6}}{m_{0}k} \left(\|\Delta \tilde{u}_{v}\|^{2} +  \|\nabla \tilde{u}_{v}\|^{6} \right), 
		\end{aligned}
	\end{equation}
	where $c_{6} = c_{6}(C, \lambda_{1}) > 0$ is independent of $k$. The final step uses the relevant Sobolev embedding to control the term $\|\nabla \tilde{u}_{v}\|^{10/3}$.
	\par
	For the last term on the right-hand side of \eqref{eq:1.98}, by condition (\textbf{A3}), Poincar\'e inequality and   H\"older inequality we have
	\begin{equation}
		\label{eq:3.94}
		\begin{aligned}
		- (\sqrt{\varepsilon} \tilde{\sigma}(t,u_{v})v(t),\varrho^{2}_{k}\tilde{u}_{v})_{g} &= \sqrt{\varepsilon} \int_{\mathcal{O}}^{} ( - \sigma_{2}(t,u_{v}), \sigma_{1}(t,u_{v}))v(t) \cdot \nabla (\varrho^{2}_{k}\tilde{u}_{v})gdx
		\\& \le \sqrt{\varepsilon }M_{0}\int_{\mathcal{O}}^{}|(-\sigma_{2}(t,u_{v}), \sigma_{1}(t,u_{v}))| |v(t)| \cdot(\varrho^{2}_{k} |\nabla \tilde{u}_{v}| +  \frac{2C}{k}|\varrho_{k}\tilde{u}_{v}|)dx 
		\\& \le \sqrt{\varepsilon L}R_{3}M_{0}\|\varrho_{k} \nabla \tilde{u}_{v}\|^{2} + \frac{2C \sqrt{\varepsilon L} R_{3} M_{0}}{\lambda^{1/2}_{1} k} \int_{\mathcal{O}}^{}\|\nabla \tilde{u}_{v}\| \|\varrho_{k} \nabla \tilde{u}_{v}\|dx
		\\& \le 2\sqrt{\varepsilon L}R_{3}M_{0}\|\varrho_{k} \nabla \tilde{u}_{v}\|^{2}  + \frac{C^{2}\sqrt{\varepsilon L}R_{3}M_{0}}{\lambda_{1} k^{2}}\|\nabla \tilde{u}_{v}\|^{2}.
		\end{aligned}
	\end{equation}
	Substituting \eqref{eq:3.90}- \eqref{eq:3.94} into \eqref{eq:1.98}, we get 
	\begin{equation}
		\label{eq:3.96}
		\begin{aligned}
	\frac{d}{dt} \|\varrho_{k}\nabla \tilde{u}_{v}\|^{2} &\le \frac{4}{k}\|\nabla \tilde{u}_{v_{t}}\| \|\tilde{u}_{v}\| + \frac{\lambda^{1/2}_{1}}{8} \|\nabla \tilde{u}_{v_{t}}\|\|\tilde{u}_{v}\| + (\frac{1}{2}\nu\alpha - \nu\lambda_{1} + 2\sqrt{\varepsilon L}R_{3}M_{0})\|\varrho_{k} \nabla \tilde{u}_{v}\|^{2} 
	\\& +  \frac{2\lambda^{1/2}_{1}c_{4}}{k}\|\Delta\tilde{u}_{v}\|^{2} + \frac{ c_{2}}{m_{0}k} \left(\|\Delta \tilde{u}_{v}\|^{2} + \|\nabla \tilde{u}_{v}\|^{6} \right) + \frac{C^{2}\sqrt{\varepsilon L}R_{3}M_{0}}{\lambda_{1} k^{2}}\|\nabla \tilde{u}_{v}\|^{2}. 
		\end{aligned}
	\end{equation}
	By Poincar\'e inequality, the identity $|\nabla \tilde{u}_{v}| = |u_{v}|$ and $\alpha < \frac{\nu \lambda_{1} - 2\sqrt{\varepsilon L}R_{3}M_{0}}{\nu }$, we get
	\begin{equation}
		\label{eq:3.97}
		\begin{aligned}
		\frac{d}{dt} \|\varrho_{k}u_{v}\|^{2} &\le \frac{4}{k \lambda^{1/2}_{1}}\|u_{v_{t}}\| \|u_{v}\| + \frac{1}{8} \|u_{v_{t}}\|\|u_{v}\| -\frac{\nu \alpha }{2}\|\varrho_{k} u_{v}\|^{2} 
		+  \frac{2\lambda^{1/2}_{1}c_{4}}{k}\|\nabla u_{v}\|^{2} 
		\\& + \frac{c_{6}}{m_{0}k} \left(\|\nabla u_{v}\|^{2} + \|u_{v}\|^{6}\right)+ \frac{C^{2}\sqrt{\varepsilon L}R_{3}M_{0}}{\lambda_{1} k}\|u_{v}\|^{2},
		\end{aligned}
	\end{equation}
	where $c_{4}, c_{6} > 0$ depend on $C, \lambda_{1}$, and $\varepsilon$, but not on $k$. \par 
	Then, by Gronwall's inequality, we get for any $t \in [0, T]$, 
	\begin{equation}
		\label{eq:3.98}
		\begin{aligned}
	&	\|\varrho_{k} u_{v}(t)\|^{2} \le \|\varrho_{k} u_{0}\|^{2}e^{- \frac{\nu \alpha}{2}t} 
		\\& + e^{ \frac{\nu \alpha}{2}t} \times \int_{0}^{t} \left( \frac{4}{k \lambda^{1/2}_{1} }\| u_{v_{t}}(s)\|\|u_{v}(s)\|  + \frac{1}{8}\| u_{v_{t}}(s)\|\|u_{v}(s)\| + \frac{2\lambda^{1/2}_{1}c_{4}}{k}\|\nabla u_{v}\|^{2} \right)ds
		\\& + e^{ \frac{\nu \alpha}{2}t} \times	\left(  \frac{c_{6}}{m_{0} k}(\|\nabla u_{v}(s)\|^{2}   + \|u_{v}(s)\|^{6} )\right)ds
		\\& +  e^{ \frac{\nu \alpha}{2}t} \times \int_{0}^{t} \left(  \frac{C^{2}\sqrt{\varepsilon L}R_{3}M_{0}}{\lambda_{1} k^{2}}\|u_{v}(s)\|^{2} \right)ds.
		\end{aligned}
	\end{equation}
	For the ﬁrst term on the right-hand side of \eqref{eq:3.98}, by $u_{0} \in H_{g}$ and Lebesgue's Dominated Convergence Theorem, we can obtain that 
	\begin{equation}
		\label{eq:4.73}
		\begin{aligned}
			e^{\frac{- \nu \alpha }{2} t}\|\varrho_{k} u_{0}\|^{2}  \le \int_{\{(x_{1},x_{2}) \in \mathcal{O}:|x_{1}| \ge \frac{k}{2} \}}^{} |u(0,x)|^{2}dx \to 0,\,\, as\,\, k \to \infty.
		\end{aligned}
	\end{equation}
For the second and third term on the right-hand side of \eqref{eq:3.98}, by Lemma \ref{lem:1.13} and   Lemma 2.2 in Wang \cite{ref Wang. B4} we have 
	\begin{equation}
		\label{eq:4.79}
		\begin{aligned}
		e^{ \frac{\nu \alpha}{2}t} \times \int_{0}^{t} \left( \frac{4}{\lambda^{1/2}_{1} k}\| u_{v_{t}}(s)\|\|u_{v}(s)\| + \frac{1}{8}\| u_{v_{t}}(s)\|\|u_{v}(s)\|  + \frac{2\lambda^{1/2}_{1}c_{4}}{k}\|\nabla u_{v}\|^{2} \right) ds \to 0,\,\, as\,\, k \to \infty.
		\end{aligned}
	\end{equation}
	For the fourth  term on the right-hand side of \eqref{eq:3.98}, by Proposition \ref{prop:1.22} and   Lemma 2.2 in Wang \cite{ref Wang. B4} we have
	\begin{equation}
		\label{eq:3.99}
		\begin{aligned}
	 e^{ \frac{\nu \alpha}{2}t} \times  \left(\int_{0}^{t} \frac{c_{6}}{m_{0}k}\left(  \|\nabla u_{v}(s)\|^{2} + \|u_{v}(s)\|^{6} \right) ds\right) \to 0, \,as\,\, k \to \infty. 
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of \eqref{eq:3.98}, by $\| v \|_{L^{2}(0, T ; H_{0,g})} \le R_{3}$ and Lemma \ref{lem:1.13} we have
	\begin{equation}
		\label{eq:4.80}
		\begin{aligned}
		e^{ \frac{\nu \alpha}{2}t} \times \int_{0}^{t} \left(  \frac{C^{2}\sqrt{\varepsilon L}R_{3}M_{0}}{\lambda_{1} k^{2}}\|u_{v}(s)\|^{2} \right)ds \to 0, \,as\,\, k \to \infty. 
		\end{aligned}
	\end{equation}
	It follows from \eqref{eq:4.73}-\eqref{eq:4.80} that for every $\varepsilon' > 0 $, there exists $K^{*} = K^{*}(\alpha, \lambda_{1}, T, u_{0}, R_{3}, \varepsilon') > 0$ such that for all $k \ge K^{*}$ and $t \in [0, T]$,
	\begin{equation}
		\label{eq:3.100}
		\begin{aligned}
			\int_{|x| \ge k}^{} |u_{v}(t,x)|^{2}dx \le  \|\varrho_{k} u_{v}(t)\|^{2}  < \varepsilon'.
		\end{aligned}
	\end{equation}
	This proof is complete.

\label{lem:3.6}
		Suppose that $(\textbf{A1})$--$(\textbf{A3})$ hold and $f \in L^{2}(0,T;V^{*}_{g})$. For any $ 0 \le M < \infty$, the set
	\begin{equation}
		\label{eq:4.36}
		\begin{aligned}
			K_{M}:= \left\{u_{v} \in C([0,T] ;  H_{g}) \cap L^{2}(0,T; V_{g}) : v\in \mathcal{S}_{M}   \right\},
		\end{aligned}
	\end{equation}
	where $u_{v}$ is the unique solution in $C([0,T] ;  H_{g}) \cap L^{2}(0,T; V_{g})$ of the equation \eqref{eq:1.56}. Then $K_{ M}$ is compact in $C([0,T] ;  H_{g}) \cap L^{2}(0,T; V_{g})$.

The proof consists of four steps. Let $\{u_{v_{n}}\}^{\infty}_{n=1}$ be a sequence in $K_{ M }$, where $u_{v_{n}}$ corresponds to the solution of \eqref{eq:1.56}. By weak compactness of $\mathcal{S}_{M}$, there exists a subsequence $\{{v_{n_{k}}}\}^{\infty}_{k=1}$ of $K_{ M }$ which converges to a limit $v \in \mathcal{S}_{M}$ weakly in $L^{2}(0, T; H_{0,g})$. Next, we prove that $u_{v_{n_{k}}} \to u_{v}$ strongly in $C([0,T]; H_{g}) \cap L^{2}([0,T]; V_{g})$. 
	\par
	\textbf{Step 1: establish weak convergence}. Since $v_{n} \to  v$ weakly in $L^{2}(0, T; H_{0,g})$, we know  the sequence $\{v_{n}\}^{\infty}_{n=1}$ is bounded in $L^{2}(0, T; H_{0,g})$, and thus by Lemma \ref{lem:1.13} we see that there exists $C_{1} = C_{1}(T, N) > 0$ such that for all $n \in \mathbb{N}$,
	\begin{equation}
		\label{eq:4.1}
		\begin{aligned}
		\| u_{v}\|^{2}_{g} + \| u_{v_{n}}\|^{2}_{g} + \|u_{v_{n}}\|^{2}_{V_{g}} \le C_{1}.
		\end{aligned}
	\end{equation}
	By \eqref{eq:4.1} and Proposition \ref{prop:1.4} we infer that there exist $ \tilde{\mathbf{u}} \in L^{2}(0, T; V_{g}) \cap  L^{\infty}(0,T; H_{g})$, $F_{0}  \in L^{2}(0, T; V_{g})$ and a subsequence of $\{u_{v_{n_{k}}}\}^{\infty}_{k=1}$ (not relabeled) such that
	\begin{equation}
		\label{eq:4.2}
		\begin{aligned}
			u_{v_{n_{k}}} \to \ \tilde{\mathbf{u}}\,\,\,\, weak-star \,\,in \,\, L^{\infty}(0, T; H_{g}),
		\end{aligned}
	\end{equation}
	\begin{equation}
		\label{eq:4.61}
		\begin{aligned}
			u_{v_{n_{k}}} \to \ \tilde{\mathbf{u}}\,\,\,\, weakly \,\,in \,\, L^{2}(0, T; V_{g}),
		\end{aligned}
	\end{equation}
	\begin{equation}
		\label{eq:4.78}
		\begin{aligned}
		F(	u_{v_{n_{k}}}) \to \ F_{0}\,\,\,\, weakly \,\,in \,\, L^{2}(0, T; V_{g}).
		\end{aligned}
	\end{equation}
	\par 
	\textbf{Step 2: prove the convergence}.
		\begin{equation}
		\label{eq:4.3}
		\begin{aligned}
			u_{v_{n_{k}}} \to \ \tilde{\mathbf{u}}\,\,\,\, strongly \,\,in \,\, C(0, T; H_{g}).
		\end{aligned}
	\end{equation}
	To that end, we will verify that the sequence $\{u_{v_{n_{k}}}\}^{\infty}_{k=1}$ is equicontinuous in $H_{g}$ on $[0, T]$, and $\{u_{v_{n_{k}}}\}^{\infty}_{k=1}$ is precompact in $H_{g}$ for every $t\in [0, T ]$. 
	For $0 \le  r \le t \le T$ and \eqref{eq:3.35}, we have for every $\eta \in H_{g},$
	\begin{equation}
		\label{eq:4.4}
		\begin{aligned}
		&(u_{v_{n_{k}}}(t) -u_{v_{n_{k}}}(r) , \eta)_{g} + \nu\int_{r}^{t}(A_{g}u_{v_{n_{k}}}(s), \eta)_{g}ds + \int_{r}^{t}(B_{g}(u_{v_{n_{k}}}(s), u_{v_{n_{k}}}(s) ), \eta)_{g}ds + \nu\int_{r}^{t}(R_{g}u_{v_{n_{k}}}(s), \eta)_{g}ds 
		\\& = \int_{r}^{t}\int_{\mathcal{O}}^{}f(s)\cdot\eta gdxds + \int_{r}^{t}(\sigma(s,u_{v_{n_{k}}}(s))v_{n_{k}}(s), \eta)_{g}ds.
		\end{aligned}
	\end{equation}
	For the second term on the left-hand side of \eqref{eq:4.4}, by the definition of $A_{g}$ we have
	\begin{equation}
		\label{eq:4.5}
		\begin{aligned}
		\left|\nu \int_{r}^{t}(A_{g}u_{v_{n_{k}}}(s), \eta)_{g}ds  \right| &\le \nu \int_{r}^{t}|(A_{g}u_{v_{n_{k}}}(s), \eta)_{g}|ds \le \nu(t-r)^{\frac{1}{2}} \|u_{v_{n_{k}}}\|_{V_{g}}\|\eta\|_{g}
		\\& \le \nu C^{\frac{1}{2}}_{1}(t-r)^{\frac{1}{2}}\|\eta\|_{g}.
		\end{aligned}
	\end{equation}
	For the third  term on the left-hand side of \eqref{eq:4.4}, by \eqref{eq:2.4} we have
	\begin{equation}
		\label{eq:4.6}
		\begin{aligned}
		\left| \int_{r}^{t}(B_{g}(u_{v_{n_{k}}}(s), u_{v_{n_{k}}}(s) ), \eta)_{g}ds    \right| &\le \int_{r}^{t}|b_{g}(u_{v_{n_{k}}}(s), u_{v_{n_{k}}}(s) ,\eta)|ds
		\\& \le c(t-r)^{\frac{1}{2}}\|u_{v_{n_{k}}}(s)\|^{\frac{1}{2}}_{g} \|u_{v_{n_{k}}}(s)\|^{\frac{1}{2}}_{V_{g}}\|u_{v_{n_{k}}}(s)\|^{\frac{1}{2}}_{V_{g}}\|A_{g}u_{v_{n_{k}}}(s)\|^{\frac{1}{2}}_{g}\|\eta\|_{g}
		\\& \le c\,\,C^{2}_{1}\, (t-r)^{\frac{1}{2}} \|\eta\|_{g}. 
		\end{aligned}
	\end{equation}
	For the fourth  term on the left-hand side of \eqref{eq:4.4}, by \eqref{eq:2.11} we have
	\begin{equation}
		\label{eq:4.7}
		\begin{aligned}
			\left|\nu \int_{r}^{t}(R_{g}u_{v_{n_{k}}}(s), \eta)_{g}ds  \right| &\le \nu \int_{r}^{t}|(R_{g}u_{v_{n_{k}}}(s), \eta)_{g}|ds \le \nu(t-r)^{\frac{1}{2}} \|R_{g}u_{v_{n_{k}}}\|_{{g}}\|\eta\|_{g}
			\\& \le \nu(t-r)^{\frac{1}{2}}\|\eta\|_{g}\frac{\|\nabla g\|_{\infty}}{m_{0}}\|u_{v_{n_{k}}}(s)\|_{V_{g}}
			\\& \le \nu(t-r)^{\frac{1}{2}} \frac{\lambda^{\frac{1}{2}}_{1} C^{\frac{1}{2}}_{1}}{16}\|\eta\|_{g}.
		\end{aligned}
	\end{equation}
	For the second term on the right-hand side of \eqref{eq:4.4}, by H\"older inequality we obtain
	\begin{equation}
		\label{eq:4.8}
		\begin{aligned}
	\left| \int_{r}^{t}\int_{\mathcal{O}}^{}f(s)\cdot\eta gdxds   \right| \le \int_{r}^{t}\int_{\mathcal{O}}^{}|f(s)\cdot\eta| gdxds \le (t-r)^{\frac{1}{2}}\|f\|_{V^{*}}  \|\eta\|_{g}. 
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of \eqref{eq:4.4}, by condition (\textbf{A2}) and \eqref{eq:4.1}, we obtain
	\begin{equation}
		\label{eq:4.9}
		\begin{aligned}
		\left| \int_{r}^{t}(\sigma(s,u_{v_{n_{k}}}(s))v_{n_{k}}(s), \eta)_{g}ds  \right| &\le \|\eta\|_{g}\int_{r}^{t} \|\sigma(s, u_{v_{n_{k}}}(s))\|_{L_{Q}}\|v_{n_{k}}(s)\|_{L^{2}(0,T;H_{0,g})}ds
		\\& \le (t-r)^{\frac{1}{2}} (MK(1 + C^{2}_{1}))^{\frac{1}{2}}\|\eta\|_{g}
		\end{aligned}
	\end{equation}
	It follows from \eqref{eq:4.5}-\eqref{eq:4.9} that there exists $C_{5} = C_{5}(\nu, \lambda_{1}, T,  M, K, C_{1}) > 0$ such that for all $0 \le r \le t \le  T$ and $\eta \in H_{g}$, 
	\begin{equation}
		\label{eq:4.10}
		\begin{aligned}
		\left|(u_{v_{n_{k}}}(t) - u_{v_{n_{k}}}(r) , \eta)_{g} \right| \le C_{5}(t-r)^{\frac{1}{2}}\|\eta\|_{g}. 
		\end{aligned}
	\end{equation}
	which shows that for all $0 \le r \le t \le  T$,
		\begin{equation}
		\label{eq:4.11}
		\begin{aligned}
			\|u_{v_{n_{k}}}(t) - u_{v_{n_{k}}}(r)\|_{g}  \le C_{5}(t-r)^{\frac{1}{2}}. 
		\end{aligned}
	\end{equation}
	Hence the sequence $\{u_{v_{n_{k}}}\}^{\infty}_{k=1}$ is equicontinuous in $H_{g}$ on $[0, T]$. \par 
	Next, we show for every $t \in [0, T]$,  the set $\{u_{v_{n_{k}}}\}^{\infty}_{k=1}$ is precompact in $V_{g}$.  Let $\varrho$ be the cut--off function as given by \eqref{eq:1.97} and $\varrho_{m}(x) =\varrho(\frac{x}{m})$ for $m \in \mathbb{N}$.  Then we have decomposed $u_{v_{n_{k}}}(t) = \tilde{\textbf{{u}}}^{m}_{v_{n_{k}}}(t) + \hat{\textbf{u}}^{m}_{v_{n_{k}}}(t)$, where $\tilde{\textbf{{u}}}^{m}_{v_{n_{k}}}(t, x) = \varrho_{m}(x)u_{v_{n_{k}}}(t, x)$ and $\hat{\textbf{u}}^{m}_{v_{n_{k}}}(t, x) = (1 - \varrho_{m}(x))u_{v_{n_{k}}}(t, x)$. By \eqref{eq:4.1}, we find that there exists $\textbf{C}_{4} =  \textbf{C}_{4}(T, N) > 0$ such that for all $k,m \in \mathbb{N}$, 
	\begin{equation}
		\label{eq:4.12}
		\begin{aligned}
		\| 	\hat{\textbf{u}}^{m}_{v_{n_{k}}}\|_{{g}} \le \textbf{C}_{4}.
		\end{aligned}
	\end{equation}
	For $m \in \mathbb{N}$, define $\textbf{Z}_{m} = \{u \in H_{g}: \|u\|_{g} \le  \textbf{C}_{4}, \,\, u(x)=0\,\, for\,\, almost\,\, all \,\, |x| \ge m \}$. By \eqref{eq:4.12} and the definition of $\hat{\textbf{u}}^{m}_{v_{n_{k}}}$, it follows that $\{\hat{\textbf{u}}^{m}_{v_{n_{k}}}\}^{\infty}_{k=1}  \subseteq \textbf{Z}_{m} $ for every $m \in \mathbb{N}$ and $t \in [0,T]$. Thanks to the compact embedding of $H^{1}(|x| < m) \hookrightarrow L^{2}(|x| < m)$, we deduce that the set $\textbf{Z}_{m}$ is precompact in $V_{g}$. Therefore, for every $m\in \mathbb{N}$ and $t \in [0,T]$, 
	\begin{equation}
		\label{eq:4.13}
		\begin{aligned}
	\{ 	\hat{\textbf{u}}^{m}_{v_{n_{k}}} \}^{\infty}_{k=1} \,\, is\,\, precompact\,\, in\,\, V_{g}.
		\end{aligned}
	\end{equation}
	In addition, by Lemma \ref{lem:3.57}, we find that for every $\varepsilon'> 0$, there exists $K^{*} = K^{*}(T, N, u_{0}, \varepsilon') > 0$ such that for all $m \ge  K^{*}$, $k \in \mathbb{N}$ and $t \in [0,T]$, 
	\begin{equation}
		\label{eq:4.14}
		\begin{aligned}
		\|\tilde{\textbf{{u}}}^{m}_{v_{n_{k}}}(t)\|_{{g}} \le  \left(\int_{|x| \ge \frac{m}{2}}^{}   |\textbf{{u}}_{v_{n_{k}}}(t,x)|^{2}dx \right)^{\frac{1}{2}} \le \frac{\varepsilon'}{2}. 
		\end{aligned}
	\end{equation}
	By \eqref{eq:4.13} and \eqref{eq:4.14}, we obtain that $\{\tilde{\textbf{{u}}}^{m}_{v_{n_{k}}}(t) + \hat{\textbf{u}}^{m}_{v_{n_{k}}}(t)\}^{\infty}_{k=1}$ has a finite open cover with radius $\varepsilon'$ in $V_{g}$, which implies that $\{u_{v_{n_{k}}}(t)\}^{\infty}_{k=1}$ is precompact in $V_{g}$. 
	\par 
	Therefore, by \eqref{eq:4.2} and the Arzela-Ascoli Theorem imply the asserted strong convergence in $C([0,T];H_g)$.
	\par 
	\textbf{Step 3: prove the convergence}.
	\begin{equation}
		\label{eq:4.62}
		\begin{aligned}
			u_{v_{n_{k}}} \to \ u_{v}\,\,\,\, strongly \,\,in \,\, C(0, T; H_{g}).
		\end{aligned}
	\end{equation}
	To prove \eqref{eq:4.62}, by \eqref{eq:4.3} we only need to show $\tilde{\mathbf{u}} = u_{v}$. Equation \eqref{eq:3.35} gives, for every $t \in [0,T]$ and $\eta \in H_{g}$,
	\begin{equation}
		\label{eq:4.63}
		\begin{aligned} 
		&(u_{v_{n_{k}}}(t), \eta)_{g} + \int_{0}^{t} (\nu A_{g}u_{v_{n_{k}}}(s), \eta)_{g} ds + \int_{0}^{t} (B_{g}(u_{v_{n_{k}}}(s), u_{v_{n_{k}}}(s)), \eta)_{g} ds 
		+ \int_{0}^{t} (\nu R_{g}u_{v_{n_{k}}}(s), \eta)_{g} ds 
		\\& = (u_{0}, \eta)_{g} + \int_{0}^{t}(f(s), \eta)_{g}ds + \int_{0}^{t}(\sigma(s,u_{v_{n_{k}}}(s))v_{n_{k}}(s), \eta)_{g}ds.
		\end{aligned}
	\end{equation}
	We now prove $\tilde{\mathbf{u}} = u_{v}$ by taking the limit of \eqref{eq:4.63} as $k \to \infty$. We ﬁrst deal with the nonlinear term on the left-hand side of \eqref{eq:4.63}. By \eqref{eq:4.3} we infer that, up to a subsequence
	\[
			u_{v_{n_{k}}}  \to \tilde{\mathbf{u}} \,\,\,a.e.\,\, on \,\,  (0, T ) \times \mathbb{R}^{2}.
	\]	
	By the definition of $F$ in Proposition \ref{prop:1.4} and its local monotonicity property, we obtain 
	\begin{equation}
		\label{eq:4.89}
		\begin{aligned}
		F(u_{v_{n_{k}}}(s)) \to F_{0}(\tilde{\mathbf{u}}(s))\,\, weakly\,\, in\,\, L^{2}(0,T; V_{g}). 
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of \eqref{eq:4.63}, we have for any $t \in [0,T]$, and $\eta \in H_{g}$,
	\begin{equation}
		\label{eq:4.65}
		\begin{aligned}
		&\int_{0}^{t}(\sigma(s,u_{v_{n_{k}}}(s))v_{n_{k}}(s), \eta)_{g}ds 
		\\& = \int_{0}^{t}((\sigma(s,u_{v_{n_{k}}}(s)) - \sigma(s,\tilde{\mathbf{u}}(s) ))v_{n_{k}}(s), \eta)_{g}ds + \int_{0}^{t}(\sigma(s,\tilde{\mathbf{u}}(s))v_{n_{k}}(s), \eta)_{g}ds. 
		\end{aligned}
	\end{equation}
	By \eqref{eq:4.3}, condition (\textbf{A3}) and H\"older inequality, we obtain
	\begin{equation}
		\label{eq:4.66}
		\begin{aligned}
		& \left| \int_{0}^{t}((\sigma(s,u_{v_{n_{k}}}(s)) - \sigma(s,\tilde{\mathbf{u}}(s) ))v_{n_{k}}(s), \eta)_{g}ds          \right| 
		\\& \le \|\eta\| \int_{0}^{t} \|\sigma(s,u_{v_{n_{k}}}(s)) - \sigma(s,\tilde{\mathbf{u}}(s)\|_{L_{Q}} \|v_{n_{k}}(s)\|_{L^{2}(0,T; H_{0,g})} ds
		\\& \le  \sqrt{M L}  \|\eta\| \left( \int_{0}^{t} \| u_{v_{n_{k}}}(s) - \tilde{\mathbf{u}}(s)\|^{2}_{g} ds      \right)^{1/2} \,\, \to\,\, 0\,\,as\,\,k\to\infty. 
		\end{aligned}
	\end{equation}
	We now deal with the last term of \eqref{eq:4.65}. Define $\mathcal{T} : L^{2}(0,T; H_{0,g}) \to H_{g}$ by
	\[
	\mathcal{T}(\omega) = \int_{0}^{t}\sigma(s,\tilde{\mathbf{u}}(s))\omega(s) g ds,\,\, \forall\, \omega \in L^{2}(0,T; H_{0,g}). 
	\]
	It follows from condition (\textbf{A2}) and \eqref{eq:4.2} that $\mathcal{T}$ is well-defined, and
	\begin{align*}
    \| \mathcal{T}(\omega) \|^{2}_{g} 
    & \le \left(\int_{0}^{t}\| \sigma(s,\tilde{\mathbf{u}}(s))\|^{2}_{L^{2}(H_{0,g}; H_{g})} ds   \right)\left(\int_{0}^{t}\|\omega(s)\|^{2}_{L^{2}(0,T; H_{0,g})} \right)
    \\& \le \left(\int_{0}^{t}\left(K(1+ \|\tilde{\mathbf{u}}(s)\|^{2}_{V_{g}}) \right)  ds   \right) \left(\int_{0}^{t}\|\omega(s)\|^{2}_{L^{2}(0,T; H_{0,g})} \right),
	\end{align*}
	which shows $\mathcal{T}$ is a bounded linear operator and thus it is weakly continuous. Since $v_{n_{k}} \rightharpoonup v$ in $ L^{2}(0,T; H_{0,g})$, we have $\mathcal{T}(v_{n_{k}}) \to \mathcal{T}(v)$ weakly in $H_{g}$. Hence, for all $t \in [0,T]$, 
	\begin{equation}
		\label{eq:4.68}
		\begin{aligned}
		\underset{k\to \infty}{\lim} \int_{0}^{t}(\sigma(s,\tilde{\mathbf{u}}(s))v_{n_{k}}(s), \eta)_{g}ds = \int_{0}^{t}(\sigma(s,\tilde{\mathbf{u}}(s))v(s), \eta)_{g}ds.
		\end{aligned}
	\end{equation}
	It follows from \eqref{eq:4.65}--\eqref{eq:4.68} that we have for any $t\in [0,T]$ and $\eta \in H_{g}$,
\begin{equation}
	\label{eq:4.87}
	\begin{aligned}
	\underset{k \to \infty}{\lim }\int_{0}^{t}(\sigma(s, u_{v_{n_{k}}}(s))v_{n_{k}}(s) ,\eta  )_{g}ds = \int_{0}^{t}(\sigma(s,\tilde{\mathbf{u}}(s))v(s), \eta)_{g}ds.
	\end{aligned}
\end{equation}
	Now, letting $k \to \infty$ in \eqref{eq:4.63}, by \eqref{eq:4.2}, \eqref{eq:4.89} and \eqref{eq:4.87}, we deduce that for any $t \in [0,T]$ and $\eta \in H_{g}$, 
	\begin{equation}
		\label{eq:4.69}
		\begin{aligned} 
			&(\tilde{\mathbf{u}}(t), \eta)_{g} + \int_{0}^{t} (\nu A_{g}\tilde{\mathbf{u}}(s), \eta)_{g} ds + \int_{0}^{t} (B_{g}(\tilde{\mathbf{u}}(s), \tilde{\mathbf{u}}(s)), \eta)_{g} ds 
			+ \int_{0}^{t} (\nu R_{g}\tilde{\mathbf{u}}(s), \eta)_{g} ds 
			\\& = (u_{0}, \eta)_{g} + \int_{0}^{t}(f(s), \eta)_{g}ds + \int_{0}^{t}(\sigma(s,\tilde{\mathbf{u}}(s))v(s), \eta)_{g}ds,
		\end{aligned}
	\end{equation}
	which shows that $\tilde{\mathbf{u}}$ is a solution of \eqref{eq:1.56}. By the uniqueness of 
	solutions,we have $ \tilde{\mathbf{u}} = u_{v}$, which together with \eqref{eq:4.3} implies \eqref{eq:4.62}.
	\par 
	\textbf{Step 4: prove the convergence}.
	\begin{equation}
		\label{eq:4.47}
		\begin{aligned}
		u_{v_{n_{k}}} \to  u_{v} \,\, strongly\,\,  in\,\,  C([0, T ]; H_{g} ) \cap L^{2}(0, T;V_{g}).
		\end{aligned}
	\end{equation}
	By \eqref{eq:2.10} and \eqref{eq:1.56} we obtain
	\begin{equation}
		\label{eq:3.16}
		\begin{aligned}
		&\frac{d}{dt} \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{g} + 2 \nu   \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{V_{g}} 
		\\& + (B_{g}(u_{v_{n_{k}}}(t), u_{v_{n_{k}}}(t)) - B_{g}(u_{v}(t), u_{v}(t)), u_{v_{n_{k}}}(t) - u_{v}(t))_{g}
		\\& \le \dfrac{\nu}{8}  \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{V_{g}} + 2  (\sigma(s, u_{v_{n_{k}}}(t))v_{n_{k}}(t) - \sigma(s, u_{v}(t))v(t),\, u_{v_{n_{k}}}(t) - u_{v}(t) )_{g}.
		\end{aligned}
	\end{equation}
	For the third term on the left-hand side of \eqref{eq:3.16}, by \eqref{eq:2.3}, Ladyzhenskaya inequality and Young's inequality  we have
	\begin{equation}
		\label{eq:3.17}
		\begin{aligned}
		&	\left|   (B_{g}(u_{v_{n_{k}}}(t), u_{v_{n_{k}}}(t), u_{v_{n_{k}}}(t) - u_{v}(t)) -B_{g}(u_{v}(t), u_{v}(t), u_{v_{n_{k}}}(t) - u_{v}(t)))_{g}\right|  
		\\& \le   \left| b_{g}(u_{v_{n_{k}}}(t), u_{v_{n_{k}}}(t), u_{v_{n_{k}}}(t) - u_{v}(t)) - b_{g}(u_{v_{n_{k}}}(t), u_{v}(t), u_{v_{n_{k}}}(t) - u_{v}(t)) \right|
		\\& +   \left| b_{g}(u_{v}(t), u_{v_{n_{k}}}(t), u_{v_{n_{k}}}(t) - u_{v}(t)) - b_{g}(u_{v}(t), u_{v}(t), u_{v_{n_{k}}}(t) - u_{v}(t)) \right|
		\\& \le   \left| b_{g}(u_{v_{n_{k}}}(t), u_{v_{n_{k}}}(t) - u_{v}(t), u_{v_{n_{k}}}(t) - u_{v}(t)) \right| +    \left| b_{g}(u_{v_{n_{k}}}(t) - u_{v}(t), u_{v}(t), u_{v_{n_{k}}}(t) - u_{v}(t)) \right|
		\\& \le   \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{L^{4}(\mathcal{O})} \|\nabla u_{v}(t)\|_{g}
		\\& \le \frac{\sqrt{2M_{0}}}{m_{0}}  \|u_{v_{n_{k}}}(t) - u_{v}(t)\|_{g}\|u_{v_{n_{k}}}(t) - u_{v}(t)\|_{V_{g}}\|u_{v}(t)\|_{V_{g}} 
		\\& \le \frac{7\nu }{8}  \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{V_{g}}  + \dfrac{2M_{0}}{7\nu m^{2}_{0}} \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{g} \|u_{v}(t)\|^{2}_{V_{g}}. 
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of \eqref{eq:3.16}, by H\"older inequality  we have
	\begin{equation}
		\label{eq:4.45}
		\begin{aligned}
		&2 \left|  (\sigma(s, u_{v_{n_{k}}}(t))u_{v_{n_{k}}}(t) - \sigma(s, u_{v}(t)))v(t),\, u_{v_{n_{k}}}(t) - u_{v}(t) )_{g} \right|
		\\& \le 2  \left( \|\sigma(s, u_{v_{n_{k}}}(t))\|_{L_{Q}}\|v_{n_{k}}(t)\|_{L^{2}(0,T; H_{0,g})} + \|\sigma(s, u_{v}(t))\|_{L_{Q}}\|v(t)\|_{L^{2}(0,T; H_{0,g})}\right) \|u_{v_{n_{k}}}(t) - u_{v}(t)\|_{g}.
		\end{aligned}
	\end{equation}
	By condition (\textbf{A2}) and \eqref{eq:4.1}, there exists a constant $C_{6}= C_{6} (N, T)>0$ such that for any $t \in [0,T]$, 
	\begin{align*}
		 2  \left( \|\sigma(s, u_{v_{n_{k}}}(t))\|_{L_{Q}} + \|\sigma(s, u_{v}(t))\|_{L_{Q}} \right) \le C_{6},
	\end{align*}
	which, along with \eqref{eq:3.16} shows, that for all $t \in [0,T]$,
	\begin{equation}
		\label{eq:4.90}
		\begin{aligned}
	&\frac{d}{dt} \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{g} + \nu   \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{V_{g}} 
		  \\& \le   \dfrac{2M_{0}}{7\nu m^{2}_{0}} \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{g} \|u_{v}(t)\|^{2}_{V_{g}}
		  + C_{6}\left( \|v_{n_{k}}(t)\|_{L^{2}(0,T; H_{0,g})} + \|v(t)\|_{L^{2}(0,T; H_{0,g})} \right)\|u_{v_{n_{k}}}(t) - u_{v}(t)\|_{g}.
		\end{aligned}
	\end{equation}
	By \eqref{eq:3.17} - \eqref{eq:4.90} and \eqref{eq:4.1}  we obtain for all $ t \in [0,T]$,
	\begin{equation}
		\label{eq:3.18}
		\begin{aligned}
	 \|u_{v_{n_{k}}}(t) - u_{v}(t)\|^{2}_{g}  &+ \nu \int_{0}^{t} \|u_{v_{n_{k}}}(t) - u_{v}(s)\|^{2}_{V_{g}}ds
	\\& \le \dfrac{2M_{0}}{7\nu m^{2}_{0}}\int_{0}^{t}\|u_{v_{n_{k}}}(s) - u_{v}(s)\|^{2}_{g} \|u_{v}(s)\|^{2}_{V_{g}} ds 
	\\& + C_{6}\int_{0}^{t}\left( \|v_{n_{k}}(s)\|_{L^{2}(0,T; H_{0,g})} + \|v(s)\|_{L^{2}(0,T; H_{0,g})} \right)\|u_{v_{n_{k}}}(s) - u_{v}(s)\|_{g}ds
	\\& \le \dfrac{2M_{0} C_{1}}{7\nu m^{2}_{0}}\|u_{v_{n_{k}}}(s) - u_{v}(s)\|^{2}_{g} 
	 + 2C_{6} M\|u_{v_{n_{k}}} - u_{v}\|_{g},
	\end{aligned}
	\end{equation}
	where $C_{1}$ and $C_{6}$ are positive constants that depend on $N$, $T$. Then by \eqref{eq:4.1} and \eqref{eq:4.62} we see that the right-hand side of \eqref{eq:3.18} converges to zero as $n \to \infty$, from which \eqref{eq:4.47} follows. 
	\par 
	This completes the proof.

Since $v \in \mathcal{A}_{M}$, $\int_{0}^{T}\|v(s)\|^{2}_{0}ds \le  M$ a.s.,  $\widetilde{W}(\cdot):= W(\cdot)+ \frac{1}{\sqrt{\varepsilon}} \int_{0}^{\cdot} v(s)ds$ is a Wiener process  with covariance form $Q$ under the probability measure $\widetilde{P}^{\varepsilon}_{v}$:
		\begin{equation}
			\label{eq:3.40}
			\begin{aligned}
				\frac{d\widetilde{P}^{\varepsilon}_{v}}{dP} = \exp\left\{ - \dfrac{1}{\sqrt{\varepsilon}} \int_{0}^{T}v(s)dW(s) - \dfrac{1}{2\varepsilon}\int_{0}^{T} \|v(s)\|^{2}_{0} ds\right\}.
			\end{aligned}
		\end{equation}
		By Girsanov's theorem, we know that $u^{\varepsilon}_{v}$ is the unique  strong solution of \eqref{eq:1.1} with $W$ replaced by $\widetilde{W}$, and hence $u^{\varepsilon}_{v}$ is the unique solution of \eqref{eq:3.39} with initial condition $u^{\varepsilon}_{v}(0) = u_{0} \in H_{g}$. 
		\par 
		Next, we prove \eqref{eq:2.32}. By \eqref{eq:3.93} and It\^o formula, taking supremum and expectation we have for $t \in [0,T]$,
	\begin{equation}
		\label{eq:2.35}
		\begin{aligned}
		\textbf{E} \underset{0 \le t\le T}{\sup} \|u^{\varepsilon}_{v}(t)\|^{2}_{g} &+ 2\nu \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}}ds 
		 +  2\nu \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} (R_{g}u^{\varepsilon}_{v}(s), u^{\varepsilon}_{v}(s) )_{g}ds 
		\\& = \|u_{0}\|^{2}_{g} + 2 \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} (f(s), u^{\varepsilon}_{v}(s))_{g}ds + 2 \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} (\sigma(s, u^{\varepsilon}_{v}(s))v(s), u^{\varepsilon}_{v}(s))_{g}ds
		\\& + \varepsilon \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t}\|\sigma(s, u^{\varepsilon}_{v}(s))\|^{2}_{L_{Q}}ds + 2\sqrt{\varepsilon}\textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} (\sigma(s, u^{\varepsilon}_{v}(s))dW(s), u^{\varepsilon}_{v}(s))_{g}ds.
		\end{aligned}
	\end{equation}
	For the last term on the left-hand side of \eqref{eq:2.35}, by \eqref{eq:2.10} we have
	\begin{equation}
		\label{eq:4.81}
		\begin{aligned}
		2\nu \textbf{E} \underset{0 \le t\le T}{\sup}\left|  \int_{0}^{t} (R_{g}u^{\varepsilon}_{v}(s), u^{\varepsilon}_{v}(s) )_{g}ds \right| \le \frac{\nu }{8} \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}}ds.
		\end{aligned}
	\end{equation}
	For the second term on the right-hand side of \eqref{eq:2.35}, by Young's inequality we have
	\begin{equation}
			\label{eq:2.36}
			\begin{aligned}
			 2 \textbf{E} \underset{0 \le t\le T}{\sup} \left| \int_{0}^{t} (f(s), u^{\varepsilon}_{v}(s))_{g}ds \right| & \le 2 \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t}\|f(s)\|_{V^{*}}\|u^{\varepsilon}_{v}(s)\|_{g} ds 	
			 \\& \le \frac{1}{\nu}\textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|f(s)\|^{2}_{V^{*}} ds + \nu  \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}}ds. 
			\end{aligned}
		\end{equation}
	For the third term on the right-hand side of \eqref{eq:2.35}, by condition (\textbf{A2}) and Young's inequality we have
	\begin{equation}
		\label{eq:2.37}
		\begin{aligned}
	& 2 \textbf{E} \underset{0 \le t\le T}{\sup} \left| \int_{0}^{t} (\sigma(s, u^{\varepsilon}_{v}(s))v(s), u^{\varepsilon}_{v}(s))_{g}ds \right|  \le 2 \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} |\sigma(s, u^{\varepsilon}_{v}(s))||v(s)||u^{\varepsilon}_{v}(s)|gdxds
	\\& \le 	\frac{2K}{\nu }\textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{g}\|v(s)\|^{2}_{L^{2}(0,T; H_{0,g})}ds  +  	\frac{\nu }{2K}\textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|\sigma(s, u^{\varepsilon}_{v}(s))\|^{2}_{L_{Q}}ds
	\\& \le \frac{2K}{\nu} \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{g}\|v(s)\|^{2}_{L^{2}(0,T; H_{0,g})}ds  +  	\frac{\nu }{2K}\textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} K( 1+ \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}}) ds. 
		\end{aligned}
	\end{equation}	
	For the fourth term on the right-hand side of \eqref{eq:2.35}, by condition (\textbf{A2}) we have	
	\begin{equation}
		\label{eq:2.38}
		\begin{aligned}
		\varepsilon \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t}\|\sigma(s, u^{\varepsilon}_{v}(s))\|^{2}_{L_{Q}}ds \le \varepsilon \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t}K(1+ \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}}) ds.
		\end{aligned}
	\end{equation}	
	For the last term on the right-hand side of \eqref{eq:2.35}, by condition (\textbf{A2}) and BDG inequality we have	
		\begin{equation}
			\label{eq:2.39}
			\begin{aligned}
		&2\sqrt{\varepsilon}\textbf{E} \underset{0 \le t\le T}{\sup} \left| \int_{0}^{t} (\sigma(s, u^{\varepsilon}_{v}(s))dW(s), u^{\varepsilon}_{v}(s))_{g}ds\right| 
		\\& \le 2 \sqrt{\varepsilon}c_{2}\textbf{E} \left( \int_{0}^{T} \|\sigma(s, u^{\varepsilon}_{v}(s))\|^{2}_{L_{Q}} \|u^{\varepsilon}_{v}(s)\|^{2}_{g}ds \right)^{1/2} 
		\\& \le \frac{1}{2}\textbf{E}  \underset{0 \le t\le T}{\sup}  \|u^{\varepsilon}_{v}(t)\|^{2}_{g} + 2\varepsilon c^{2}_{2} \textbf{E} \int_{0}^{T} K(1+ \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}})ds. 
			\end{aligned}
		\end{equation}
	By \eqref{eq:2.36}-\eqref{eq:2.39} we obtain that for all $t \in [0, T ]$ with $\varepsilon < \frac{\nu }{8K(1+2c^{2}_{2})}$, 
	\begin{equation}
		\label{eq:2.40}
		\begin{aligned}
 & \textbf{E}\left( \frac{1}{2} \underset{0 \le t\le T}{\sup}  \left( \|u^{\varepsilon}_{v}(t)\|^{2}_{g} + \nu  \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}}ds \right) \right)
 \\& \le \|u_{0}\|^{2}_{g} + \frac{1}{\nu}\textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|f(s)\|^{2}_{V^{*}} ds + \frac{2K}{\nu} \textbf{E} \underset{0 \le t\le T}{\sup} \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{g}\|v(s)\|^{2}_{L^{2}(0,T; H_{0,g})}ds + \frac{\nu T}{8}.
		\end{aligned}
	\end{equation}	
	Since $u_{0}\in H_{g}$ with $\| u_{0}\| \le R_{4}$ and $v \in \mathcal{A}_{M}$, then by Gronwall’s inequality implies that for all $t \in [0, T ]$, 	
		\begin{equation}
			\label{eq:2.49}
			\begin{aligned}
		&\textbf{E}\left(   \underset{0 \le t\le T}{\sup}\left( \|u^{\varepsilon}_{v}(t)\|^{2}_{g} + \nu  \int_{0}^{t} \|u^{\varepsilon}_{v}(s)\|^{2}_{V_{g}}ds \right)  \right) 
		\\& \le \left(2R^{2}_{4} + \frac{2}{\nu}\textbf{E}\int_{0}^{T} \|f(s)\|^{2}_{V^{*}} ds + \frac{\nu T}{4} \right) e^{\frac{4K}{\nu }\int_{0}^{T}\|v(s)\|^{2}_{L^{2}(0,T; H_{0,g})} ds}, 
			\end{aligned}
		\end{equation}
	which implies \eqref{eq:2.32} and thus completes the proof.

Let	 $u^{\varepsilon}_{v^{\varepsilon}}  = \mathcal{G}^{\varepsilon}\left( W + \varepsilon^{-\frac{1}{2}}\int_{0}^{\cdot} v^{\varepsilon}(t)dt \right)$. By Lemma  \ref{lem:3.6}, $u^{\varepsilon}_{v^{\varepsilon}}$ satisfies 
		\begin{equation}
			\label{eq:3.22}
			\begin{aligned}
	du^{\varepsilon}_{v^{\varepsilon}}(t) + (\nu A_{g}u^{\varepsilon}_{v^{\varepsilon}}(t) + B_{g}(u^{\varepsilon}_{v^{\varepsilon}}(t), u^{\varepsilon}_{v^{\varepsilon}}(t)) + \nu R_{g}u^{\varepsilon}_{v^{\varepsilon}}(t))dt &= f(t)dt + \sigma(t, u^{\varepsilon}_{v^{\varepsilon}}(t))v^{\varepsilon}(t)dt
	\\& +\sqrt{\varepsilon}\sigma(t, u^{\varepsilon}_{v^{\varepsilon}}(t))dW(t),
			\end{aligned}
		\end{equation}
	with initial condition $u^{\varepsilon}_{v^{\varepsilon}}(0) = u_{0} \in H_{g}$. Let $u_{v^{\varepsilon}} = \mathcal{G}^{0}\left(\int_{0}^{\cdot} v^{\varepsilon}(t)dt \right)$. Then $u_{v^{\varepsilon}}$ is the solution of 
	\begin{equation}
		\label{eq:3.25}
		\begin{aligned}
			du_{v^{\varepsilon}}(t) + (\nu A_{g}u_{v^{\varepsilon}}(t) + B_{g}(u_{v^{\varepsilon}}(t), u_{v^{\varepsilon}}(t)) + \nu R_{g}u_{v^{\varepsilon}}(t))dt = f(t)dt + \sigma(t, u_{v^{\varepsilon}}(t))v^{\varepsilon}(t)dt,
		\end{aligned}
	\end{equation}
	with initial condition $u_{v^{\varepsilon}}(0) = u_{0} \in H_{g}$. We will now show that $ u^{\varepsilon}_{v^{\varepsilon}}(t)$ converges to $u_{v}$ in $C([0, T ]; H_{g}) \cap L^{2}(0, T ; V_{g} )$ in distribution as $\varepsilon \to 0$. By \eqref{eq:3.22} and \eqref{eq:3.25}, we have 
	\begin{equation}
		\label{eq:4.15}
		\begin{aligned}
		&d(u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t)) + \nu A_{g}(u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t))dt + (B_{g}(u^{\varepsilon}_{v^{\varepsilon}}(t), u^{\varepsilon}_{v^{\varepsilon}}(t)) - B_{g}(u_{v^{\varepsilon}}(t), u_{v^{\varepsilon}}(t)))dt 
		\\& +\nu R_{g}(u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t))dt 
		\\&= (\sigma(t, u^{\varepsilon}_{v^{\varepsilon}}(t))v^{\varepsilon}(t) - \sigma(t, u_{v^{\varepsilon}}(t))v^{\varepsilon}(t))dt + \sqrt{\varepsilon}\sigma(t, u^{\varepsilon}_{v^{\varepsilon}})dW(t), 
		\end{aligned}
	\end{equation}
	with initial value $u^{\varepsilon}_{v^{\varepsilon}}(0) - u_{v^{\varepsilon}}(0) = 0$. By \eqref{eq:4.15} and It\^o formula, we obtain
	\begin{equation}
		\label{eq:3.27}
		\begin{aligned}
			&\| u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t)\|^{2}_{g} + 2\nu  \int_{0}^{t}\| u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s) \|^{2}_{V_{g}} ds
			 + 2 \nu \int_{0}^{t}(R_{g}(u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)), u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}ds 
			 \\& + 2\int_{0}^{t}(B_{g}(u^{\varepsilon}_{v^{\varepsilon}}(s), u^{\varepsilon}_{v^{\varepsilon}}(s)) -B_{g}(u_{v^{\varepsilon}}(s), u_{v^{\varepsilon}}(s)) , u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g} ds
			 \\& = 2 \int_{0}^{t} (\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))v^{\varepsilon}(s) - \sigma(s,u_{v^{\varepsilon}}(s))v^{\varepsilon}(s), u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}ds + \varepsilon \int_{0}^{t} tr\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))Q\sigma^{*}(s,u^{\varepsilon}_{v^{\varepsilon}}(s))ds
			\\& + 2\sqrt{\varepsilon}\int_{0}^{t} (\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))dW(s),u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}.
		\end{aligned}	
	\end{equation}
	For the third term on the left-hand side of  \eqref{eq:3.27}, by Lemma \ref{lem:3.65}, we have 
	\begin{equation}
		\label{eq:4.16}
		\begin{aligned}
	2 \nu \left|\int_{0}^{t}(R_{g}(u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)), u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}ds\right| 
	 \le \frac{\nu }{8} \int_{0}^{t}\|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{V_{g}}ds. 
		\end{aligned}
	\end{equation}
	For the fourth term on the left-hand side of  \eqref{eq:3.27}, by \eqref{eq:2.32}, \eqref{eq:1.16} and Young's inequality, we have 
	\begin{equation}
		\label{eq:4.17}
		\begin{aligned}
		& 2\left| \int_{0}^{t}(B_{g}(u^{\varepsilon}_{v^{\varepsilon}}(s), u^{\varepsilon}_{v^{\varepsilon}}(s)) -B_{g}(u_{v^{\varepsilon}}(s), u_{v^{\varepsilon}}(s)) , u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g} \right|
		\\& \le 2\left|\int_{0}^{t} b_{g}(u^{\varepsilon}_{v^{\varepsilon}}(s), u^{\varepsilon}_{v^{\varepsilon}}(s)- u_{v^{\varepsilon}}(s), u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))ds \right| 
		\\& +2\left|\int_{0}^{t} b_{g}(u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s), u_{v^{\varepsilon}}(s), u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))ds \right|
		\\& \le 2\int_{0}^{t}\int_{\mathcal{O}}^{} |u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)| |\nabla u_{v^{\varepsilon}}(s) ||u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)| g dxds
		\\& \le 2\int_{0}^{t} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{L^{4}} \|\nabla u_{v^{\varepsilon}}(s)\|_{g}ds
		\\& \le \frac{2\sqrt{2M_{0}}}{m_{0}}\int_{0}^{t} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|_{g}\|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|_{V_{g}} \| u_{v^{\varepsilon}}(s)\|_{V_{g}}ds
		\\& \le \frac{7\nu}{8}\int_{0}^{t} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{V_{g}}ds + \frac{16M_{0}}{7\nu m^{2}_{0}}\int_{0}^{t} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{g}\| u_{v^{\varepsilon}}(s)\|^{2}_{V_{g}}ds. 
		\end{aligned}
	\end{equation}
	For the first term on the right-hand side of  \eqref{eq:3.27}, by \eqref{eq:2.32}, \eqref{eq:1.16} and H\"older inequality, we have
	\begin{equation}
		\label{eq:4.18}
		\begin{aligned}
		&2 \left| \int_{0}^{t} (\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s)v^{\varepsilon}(s) - \sigma(s,u_{v^{\varepsilon}}(s))v^{\varepsilon}(s), u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}ds  \right|
		\\& \le 2\int_{0}^{t}\|\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))-\sigma(s,u_{v^{\varepsilon}}(s)) \|_{L_{Q}} \|v^{\varepsilon}(s)\|_{L^{2}(0,T; H_{0,g})} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|_{g}ds
		\\& \le 2\sqrt{L} \int_{0}^{t}\|v^{\varepsilon}(s)\|_{L^{2}(0,T; H_{0,g})} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{g}ds. 
		\end{aligned}
	\end{equation}
	It follows from \eqref{eq:4.16} - \eqref{eq:4.18} that for all $t \in [0,T]$,  
	\begin{equation}
		\label{eq:4.19}
		\begin{aligned}
		& \| u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t)\|^{2}_{g} + \nu  \int_{0}^{t}\| u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s) \|^{2}_{V_{g}} ds
		\\&  \le \frac{16M_{0}}{7\nu m^{2}_{0}}\int_{0}^{t} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{g}\| u_{v^{\varepsilon}}(s)\|^{2}_{V_{g}}ds + 2\sqrt{L} \int_{0}^{t}\|v^{\varepsilon}(s)\|_{L^{2}(0,T; H_{0,g})} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{g}ds 
		\\& +  \varepsilon \int_{0}^{t} \|\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))\|^{2}_{L_{Q}}ds + 2\sqrt{\varepsilon}\int_{0}^{t} (\sigma(s,u^{\varepsilon}(s)_{v^{\varepsilon}})dW(s),u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}.
		\end{aligned}
	\end{equation}
		Given $ N >0$ and $\varepsilon \in (0,1)$, define a stopping time 
	\begin{equation}
		\label{eq:3.29}
		\begin{aligned}
			\tau_{N,\varepsilon} := inf\left\{t \ge 0:  \|u^{\varepsilon}_{v^{\varepsilon}}(t)\|^{2}_{g}  \ge  N\right\} \wedge T.
		\end{aligned}
	\end{equation}
	By \eqref{eq:4.19} we have for all $t \in [0,T]$,  
	\begin{equation}
		\label{eq:4.20}
		\begin{aligned}
		& \underset{0\le r\le t}{\sup} \left( \| u^{\varepsilon}_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon}) - u_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon})\|^{2}_{g} + \nu  \int_{0}^{r \wedge \tau_{N,\varepsilon}}\| u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s) \|^{2}_{V_{g}} ds \right)
		\\&  \le \int_{0}^{r \wedge \tau_{N,\varepsilon}} \left( \frac{16M_{0}}{7\nu m^{2}_{0}}\|u_{v^{\varepsilon}}(s)\|^{2}_{V_{g}} + 2\sqrt{L}\|v^{\varepsilon}(s)\|_{L^{2}(0,T; H_{0,g})}  \right) \underset{0 \le r \le s}{\sup}\|u^{\varepsilon}_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon}) - u_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon})\|^{2}_{g}ds 
		\\& +  \varepsilon \int_{0}^{r \wedge \tau_{N,\varepsilon}}\|\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))\|^{2}_{L_{Q}}ds + 2\sqrt{\varepsilon}\underset{0\le r\le t}{\sup}\int_{0}^{r \wedge \tau_{N,\varepsilon}} (\sigma(s,u^{\varepsilon}(s)_{v^{\varepsilon}})dW(s),u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}.
		\end{aligned}
	\end{equation}
	By \eqref{eq:4.20} and Gronwall's inequality, we have that for any $t \in [0,T]$, 
	\begin{equation}
		\label{eq:4.21}
		\begin{aligned}
		& \underset{0\le r\le T}{\sup} \left( \| u^{\varepsilon}_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon}) - u_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon})\|^{2}_{g} + \nu  \int_{0}^{r \wedge \tau_{N,\varepsilon}}\| u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s) \|^{2}_{V_{g}} ds \right)
	    \\& \le  \varepsilon e^{c_{8}}  \int_{0}^{r \wedge \tau_{N,\varepsilon}} \|\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s) )\|^{2}_{L_{Q}} ds
		+ 2\sqrt{\varepsilon}e^{c_{8}}  \underset{0\le r\le T}{\sup}\int_{0}^{T \wedge \tau_{N,\varepsilon}} (\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))dW(s),u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g}, 
		\end{aligned}
	\end{equation}
	where $c_{8} = (\frac{16M_{0}}{7m^{2}_{0}}C_{1} + 2\sqrt{LM})T > 0$.  For the first term on the right-hand side \eqref{eq:4.21}, by condition (\textbf{A2}) and \eqref{eq:4.38}, we have 
	\begin{equation}
		\label{eq:4.22}
		\begin{aligned}
		  \underset{\varepsilon \to 0}{\rm{lim}}\,\varepsilon e^{c_{8}}  \int_{0}^{T \wedge \tau_{N,\varepsilon}} \|\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s) )\|^{2}_{L_{Q}} ds
		  \le \underset{\varepsilon \to 0}{\rm{lim}}\,\varepsilon e^{c_{8}} K\int_{0}^{T \wedge \tau_{N,\varepsilon}} (1+ \|u^{\varepsilon}_{v^{\varepsilon}}(s)\|^{2}_{V_{g}}) ds
		 = 0, \mathbb{P} - almost\,surely. 
		\end{aligned}
	\end{equation}
	In addition, by Lemma  \ref{lem:1.13}, we have that there exists $ C'_{1} = C'_{1}(M, T) > 0$ such that 
	\begin{equation}
		\label{eq:4.23}
		\begin{aligned}
			\underset{\varepsilon \in (0, 1)}{\sup} \|u_{v^{\varepsilon}} \|_{g} \le C'_{1}. 
		\end{aligned}
	\end{equation}
	For the last term on the right-hand side of \eqref{eq:4.21}, by \eqref{eq:4.22}, \eqref{eq:4.23} and Doob's maximal inequality, we obtain
	\begin{equation}
		\label{eq:4.24}
		\begin{aligned}
	& \underset{\varepsilon \to 0}{\rm{lim}}   \textbf{E} \left[ \underset{0\le r\le T}{\sup} \left|  \int_{0}^{r \wedge \tau_{N,\varepsilon}}2\sqrt{\varepsilon}\, e^{c_{8}}\, (\sigma(s,u^{\varepsilon}_{v^{\varepsilon}}(s))dW(s),u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s))_{g} \right|^{2} \right]
	\\& \le  \underset{\varepsilon \to 0}{\rm{lim}} 16 \varepsilon e^{2c_{8}}  \textbf{E} \left[\int_{0}^{T \wedge \tau_{N,\varepsilon}} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{g} \| \sigma(s,u^{\varepsilon}(s))\|^{2}_{L_{Q}}ds\right]
	\\& \le 16e^{2c_{8}} (N + C'_{1})^{2} \underset{\varepsilon \to 0}{\rm{lim}} \textbf{E} \left[\varepsilon \int_{0}^{ T \wedge \tau_{N,\varepsilon}} \| \sigma(s,u^{\varepsilon}(s))\|^{2}_{L_{Q}} ds\right]
	\\& =0.
		\end{aligned}
	\end{equation}
	It follows from \eqref{eq:4.21}, \eqref{eq:4.22} and \eqref{eq:4.24} that 
	\begin{equation}
		\label{eq:4.25}
		\begin{aligned}
		\underset{\varepsilon \to 0}{\rm{lim}}\,\,  \underset{0\le r\le T}{\sup} \|u^{\varepsilon}_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon}) - u_{v^{\varepsilon}}(r \wedge \tau_{N,\varepsilon})\|^{2}_{g} = 0 \,\,in\, \, probability, 
		\end{aligned}
	\end{equation}
	and 
	\begin{equation}
		\label{eq:4.26}
		\begin{aligned}
			\underset{\varepsilon \to 0}{\rm{lim}}  \int_{0}^{T\wedge \tau_{N,\varepsilon}} \|u^{\varepsilon}_{v^{\varepsilon}}(s) - u_{v^{\varepsilon}}(s)\|^{2}_{V_{g}} ds = 0 \,\,in\, \, probability.
		\end{aligned}
	\end{equation}
	On the other hand by  \eqref{eq:2.32} and  \eqref{eq:3.29} we have for all $\varepsilon \in (0,1)$,  
	\begin{equation}
		\label{eq:4.27}
		\begin{aligned}
		\mathbb{P}(\tau_{N,\varepsilon} < T  ) \le \mathbb{P}\left(\underset{t \in [0,T]}{\sup} \|u^{\varepsilon}_{v^{\varepsilon}}(t)\|_{g} \ge N \right) \le \dfrac{1}{N^{2}}\textbf{E}\left( \underset{t \in [0,T]}{\sup} \|u^{\varepsilon}_{v^{\varepsilon}}(t)\|^{2}_{g}\right) \le \frac{M_{1}}{N^{2}},
		\end{aligned}
	\end{equation}
	where $M_{1} = M_{1}( T, M) >0$. It follows from \eqref{eq:4.27} that for every $\eta > 0$,
	\begin{align*}
		& \mathbb{P}\left(\underset{t \in [0,T]}{\sup}\|u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t) \|_{g}  > \eta \right) 
		\\& \le \mathbb{P}\left(\underset{t \in [0,T]}{\sup}\|u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t) \|_{g}  > \eta, \tau_{N,\varepsilon} =T \right) + \mathbb{P}\left(\underset{t \in [0,T]}{\sup}\|u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t) \|_{g}  > \eta, \tau_{N,\varepsilon} < T \right) 
		\\& \le \mathbb{P}\left(\underset{t \in [0,T]}{\sup}\|u^{\varepsilon}_{v^{\varepsilon}}(t \wedge \tau_{N,\varepsilon}) - u_{v^{\varepsilon}}(t \wedge \tau_{N,\varepsilon}) \|_{g}  > \eta \right) + \frac{M_{1}}{N^{2}}.
	\end{align*}
	First letting $\varepsilon \to 0$ and  then $N \to \infty$, we get from \eqref{eq:4.25} that 
	\begin{equation}
		\label{eq:4.29}
		\begin{aligned}
		\underset{\varepsilon \to 0}{\rm{lim}} \left( u^{\varepsilon}_{v^{\varepsilon}} - u_{v^{\varepsilon}} \right) = 0 \,\, in\,\, C([0,T]; H_{g}) \,\, in\, probability.
		\end{aligned}
	\end{equation}
	Similarly, by \eqref{eq:4.27} we have, for every $\eta > 0$, 
	\begin{align*}
		& \mathbb{P}\left(\int_{0}^{T} \|u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t) \|^{2}_{V_{g}}dt  > \eta^{2} \right) 
		\\& \le \mathbb{P}\left(\int_{0}^{T} \|u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t) \|^{2}_{V_{g}} dt > \eta^{2}, \tau_{N,\varepsilon} =T \right) + \mathbb{P}\left(\int_{0}^{T} \|u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t) \|^{2}_{V_{g}}dt  > \eta^{2}, \tau_{N,\varepsilon} < T \right) 
		\\& \le \mathbb{P}\left(\int_{0}^{T \wedge \tau_{N,\varepsilon}} \|u^{\varepsilon}_{v^{\varepsilon}}(t) - u_{v^{\varepsilon}}(t) \|^{2}_{V_{g}}dt  > \eta^{2} \right) + \frac{M_{1}}{N^{2}}.
		\end{align*}
		First letting $\varepsilon \to 0$ and then $N \to \infty$, we get from \eqref{eq:4.26} that 
		\begin{equation}
			\label{eq:4.31}
			\begin{aligned}
				\underset{\varepsilon \to 0}{\rm{lim}} \left( u^{\varepsilon}_{v^{\varepsilon}} - u_{v^{\varepsilon}} \right) = 0 \,\, in\,\, L^{2}(0,T; V_{g}) \,\, in\, probability.
			\end{aligned}
		\end{equation}
		It follows from \eqref{eq:4.29} and \eqref{eq:4.31} that 
		\begin{equation}
			\label{eq:4.32}
			\begin{aligned}
				\underset{\varepsilon \to 0}{\rm{lim}} \left( u^{\varepsilon}_{v^{\varepsilon}} - u_{v^{\varepsilon}} \right) = 0 \,\, in\,\, C([0,T]; H_{g}) \cap  L^{2}(0,T; V_{g}) \,\, in\, probability.
			\end{aligned}
		\end{equation}
		By assumption, we know $\{ v^{\varepsilon} \}$ converges in distribution to $v$ as $\mathcal{S}_{M}$-valued random element, and hence by Skorokhod's Theorem, there exist a probability space $(\tilde{\Omega}, \tilde{\mathcal{F}}, \tilde{\mathbb{P}}  )$ and $\mathcal{S}_{M}$-valued random variables $\tilde{v}^{\varepsilon}$ and $\tilde{v}$ on $(\tilde{\Omega}, \tilde{\mathcal{F}}, \tilde{\mathbb{P}}  )$ such that the law of $\tilde{v}^{\varepsilon}$ and $\tilde{v}$ are equal to that of $v^{\varepsilon}$ and $v$ respectively. Furthermore, $\{\tilde{v}^{\varepsilon}\}$ converges to $\tilde{v}$ almost surely in $\mathcal{S}_{M}$, it follows from Lemma \ref{lem:3.6} that
		\begin{equation}
			\label{eq:4.33}
			\begin{aligned}
			u_{\tilde{v}^{\varepsilon}} \to  u_{\tilde{v}}	\,\, in\,\, C([0,T]; H_{g}) \cap  L^{2}(0,T; V_{g}) \,\, almost\,\, surely,
			\end{aligned}
		\end{equation}
		and hence it is also convergent in distribution, which implies that 
\begin{equation}
	\label{eq:4.34}
	\begin{aligned}
		u_{v^{\varepsilon}} \to  u_{v}	\,\, in\,\, C([0,T]; H_{g}) \cap  L^{2}(0,T; V_{g}) \,\, in \,\, distribution.
	\end{aligned}
\end{equation}
	By \eqref{eq:4.33} and \eqref{eq:4.34} we infer that 
	\begin{equation}
		\label{eq:4.35}
		\begin{aligned}
			u^{\varepsilon}_{v^{\varepsilon}} \to  u_{v}	\,\, in\,\, C([0,T]; H_{g}) \cap  L^{2}(0,T; V_{g}) \,\, in \,\, distribution, 
		\end{aligned}
	\end{equation}
	as desired. The proof is thus completed.
